// Текст закона для сайта (подключается при открытии раздела)
(window.LAW_DATA = window.LAW_DATA || {})["gk"] = {"items":[{"h":"Часть первая"},{"h":"Раздел I. Общие положения"},{"h":"Глава 1. Гражданское законодательство"},{"n":"Статья 1","title":"Основные начала гражданского законодательства","sub":[{"n":"1","text":"Гражданское законодательство строится на принципах признания равенства участников регулируемых им отношений, неприкосновенности собственности, свободы заключения договора, недопустимости произвольного вмешательства в частные дела, а также необходимости беспрепятственного осуществления и восстановления нарушенных прав."},{"n":"2","text":"Физические и юридические лица приобретают и осуществляют свои гражданские права по собственной воле и в своих интересах. Они свободны в установлении своих прав и обязанностей на основе договора и в определении любых не противоречащих законодательству условий договора."},{"n":"3","text":"Товары, услуги и денежные средства свободно перемещаются на всей территории Российской Федерации. Ограничения перемещения товаров и услуг могут вводиться в соответствии с федеральным законом, если это необходимо для обеспечения безопасности, защиты жизни и здоровья людей."}]},{"n":"Статья 2","title":"Отношения, регулируемые гражданским законодательством","sub":[{"n":"1","text":"Гражданское законодательство определяет правовое положение участников гражданского оборота, основания возникновения и порядок осуществления права собственности и иных вещных прав, прав на результаты интеллектуальной деятельности и приравненные к ним средства индивидуализации."},{"n":"2","text":"Настоящее законодательство регулирует договорные и иные обязательства, а также другие имущественные и личные неимущественные отношения, основанные на равенстве, автономии воли и имущественной самостоятельности участников."},{"n":"3","text":"К имущественным отношениям, основанным на административном или ином властительном подчинении одной стороны другой, в том числе к налоговым и финансовым отношениям, гражданское законодательство не применяется, если иное не предусмотрено законодательством."}]},{"n":"Статья 3","title":"Действие гражданского законодательства во времени","sub":[{"n":"1","text":"Акты гражданского законодательства не имеют обратной силы и применяются к отношениям, возникшим после введения их в действие."},{"n":"2","text":"По отношениям, возникшим до введения в действие акта гражданского законодательства, он применяется к правам и обязанностям, возникшим после введения его в действие."},{"n":"3","text":"Отношения сторон по договору, заключенному до введения в действие акта гражданского законодательства, регулируются в соответствии с правилами, действовавшими при заключении договора."}]},{"n":"Статья 4","title":"Аналогия закона и аналогия права","sub":[{"n":"1","text":"В случаях, когда предусмотренные гражданским законодательством отношения прямо не урегулированы законодательством или соглашением сторон и отсутствует применимый к ним обычай, к таким отношениям, если это не противоречит их существу, применяется гражданское законодательство, регулирующее сходные отношения (аналогия закона)."},{"n":"2","text":"При невозможности использования аналогии закона права и обязанности сторон определяются исходя из общих начал и смысла гражданского законодательства (аналогия права) и требований добросовестности, разумности и справедливости."},{"n":"3","text":"Не допускается применение по аналогии норм, ограничивающих гражданские права и устанавливающих ответственность, если это прямо не предусмотрено законом."}]},{"h":"Глава 2. Возникновение и осуществление гражданских прав"},{"n":"Статья 5","title":"Возникновение гражданских прав и обязанностей","sub":[{"n":"1","text":"Гражданские права и обязанности возникают из оснований, предусмотренных законом и иными правовыми актами, а также из действий граждан и юридических лиц, которые хотя и не предусмотрены законом или такими актами, но в силу общих начал и смысла гражданского законодательства порождают гражданские права и обязанности."},{"n":"2","text":"В соответствии с этим гражданские права и обязанности возникают:"},{"n":"1)","text":"из договоров и иных сделок, предусмотренных законом, а также из договоров и иных сделок, хотя и не предусмотренных законом, но не противоречащих ему;","lvl":1},{"n":"2)","text":"из решений собраний в случаях, предусмотренных законом;","lvl":1},{"n":"3)","text":"из актов государственных органов и органов местного самоуправления, которые предусмотрены законом в качестве основания возникновения гражданских прав и обязанностей;","lvl":1},{"n":"4)","text":"из судебного решения, установившего гражданские права и обязанности;","lvl":1},{"n":"5)","text":"в результате приобретения имущества по основаниям, допускаемым законом;","lvl":1},{"n":"6)","text":"в результате создания произведений науки, литературы, искусства, изобретений и иных результатов интеллектуальной деятельности;","lvl":1},{"n":"7)","text":"вследствие причинения вреда другому лицу;","lvl":1},{"n":"8)","text":"вследствие неосновательного обогащения;","lvl":1},{"n":"9)","text":"вследствие иных действий граждан и юридических лиц;","lvl":1},{"n":"10)","text":"вследствие событий, с которыми закон или иной правовой акт связывает наступление гражданско-правовых последствий.","lvl":1},{"n":"3","text":"Права на имущество, подлежащее государственной регистрации, возникают с момента регистрации соответствующих прав на него, если иное не установлено законом."}]},{"n":"Статья 6","title":"Осуществление гражданских прав и пределы их осуществления","sub":[{"n":"1","text":"Граждане и юридические лица осуществляют принадлежащие им гражданские права своей волей и в своем интересе. Они свободны в установлении своих прав и обязанностей на основе договора и в определении любых не противоречащих законодательству условий договора."},{"n":"2","text":"Не допускаются осуществление гражданских прав исключительно с намерением причинить вред другому лицу, действия в обход закона с противоправной целью, а также иное заведомо недобросовестное осуществление гражданских прав (злоупотребление правом)."},{"n":"3","text":"В случае несоблюдения требований, предусмотренных пунктом 2 настоящей статьи, суд с учетом характера и последствий допущенного злоупотребления отказывает лицу в защите принадлежащего ему права полностью или частично."},{"n":"4","text":"Добросовестность участников гражданских правоотношений и разумность их действий предполагаются."}]},{"n":"Статья 7","title":"Защита гражданских прав","sub":[{"n":"1","text":"Защита нарушенных или оспоренных гражданских прав осуществляется в соответствии с подведомственностью дел, установленной процессуальным законодательством, судом, арбитражным судом или третейским судом."},{"n":"2","text":"Защита гражданских прав осуществляется путем:"},{"n":"1)","text":"признания права;","lvl":1},{"n":"2)","text":"восстановления положения, существовавшего до нарушения права, и пресечения действий, нарушающих право или создающих угрозу его нарушения;","lvl":1},{"n":"3)","text":"признания оспоримой сделки недействительной и применения последствий ее недействительности, применения последствий недействительности ничтожной сделки;","lvl":1},{"n":"4)","text":"признания недействительным решения собрания;","lvl":1},{"n":"5)","text":"признания недействительным акта государственного органа или органа местного самоуправления;","lvl":1},{"n":"6)","text":"самозащиты права;","lvl":1},{"n":"7)","text":"присуждения к исполнению обязанности в натуре;","lvl":1},{"n":"8)","text":"возмещения убытков;","lvl":1},{"n":"9)","text":"взыскания неустойки;","lvl":1},{"n":"10)","text":"компенсации морального вреда;","lvl":1},{"n":"11)","text":"прекращения или изменения правоотношения;","lvl":1},{"n":"12)","text":"неприменения судом акта государственного органа или органа местного самоуправления, противоречащего закону;","lvl":1},{"n":"13)","text":"иными способами, предусмотренными законом.","lvl":1}]},{"h":"Глава 3. Статус физических и юридических лиц"},{"n":"Статья 8","title":"Гражданская правоспособность и дееспособность","sub":[{"n":"1","text":"Способность иметь гражданские права и нести обязанности (гражданская правоспособность) признается в равной мере за всеми гражданами."},{"n":"2","text":"Правоспособность гражданина возникает в момент его рождения и прекращается со смертью."},{"n":"3","text":"Способность гражданина своими действиями приобретать и осуществлять гражданские права, создавать для себя гражданские обязанности и исполнять их (гражданская дееспособность) возникает в полном объеме с наступлением совершеннолетия, то есть по достижении восемнадцатилетнего возраста."},{"n":"4","text":"В случаях, когда законом допускается вступление в брак до достижения восемнадцати лет, гражданин приобретает дееспособность в полном объеме со времени вступления в брак. Полномочия полной дееспособности могут быть также предоставлены несовершеннолетнему путем эмансипации."}]},{"n":"Статья 9","title":"Имя гражданина","sub":[{"n":"1","text":"Гражданин приобретает и осуществляет права и обязанности под своим именем, включающим фамилию и собственно имя, а также отчество, если иное не вытекает из закона или национального обычая."},{"n":"2","text":"В случаях и в порядке, предусмотренных законом, гражданин может использовать псевдоним (вымышленное имя)."},{"n":"3","text":"Гражданин вправе переменить свое имя в порядке, установленном законом. Перемена имени не является основанием для прекращения или изменения его прав и обязанностей, приобретенных под прежним именем."}]},{"n":"Статья 10","title":"Место жительства гражданина","sub":[{"n":"1","text":"Местом жительства признается место, где гражданин постоянно или преимущественно проживает."},{"n":"2","text":"Местом жительства несовершеннолетних, не достигших четырнадцати лет, или граждан, находящихся под опекой, признается место жительства их законных представителей — родителей, усыновителей или опекунов."}]},{"n":"Статья 11","title":"Акты гражданского состояния","sub":[{"n":"1","text":"Актами гражданского состояния признаются действия граждан или события, влияющие на возникновение, изменение или прекращение прав и обязанностей, а также характеризующие правовое состояние граждан."},{"n":"2","text":"Государственной регистрации подлежат следующие акты гражданского состояния: рождение, заключение брака, расторжение брака, усыновление (удочерение), установление отцовства, перемена имени, смерть гражданина."},{"n":"3","text":"Регистрация актов гражданского состояния производится органами записи актов гражданского состояния путем внесения соответствующих записей в книги регистрации актов гражданского состояния."}]},{"n":"Статья 12","title":"Предпринимательская деятельность гражданина","sub":[{"n":"1","text":"Гражданин вправе заниматься предпринимательской деятельностью без образования юридического лица с момента государственной регистрации в качестве индивидуального предпринимателя."},{"n":"2","text":"Гражданин, осуществляющий предпринимательскую деятельность без образования юридического лица с нарушением требований о государственной регистрации, не вправе ссылаться в отношении заключенных им при этом сделок на то, что он не является предпринимателем."},{"n":"3","text":"К предпринимательской деятельности граждан, осуществляемой без образования юридического лица, соответственно применяются правила настоящего Кодекса, которые регулируют деятельность юридических лиц, являющихся коммерческими организациями, если иное не вытекает из закона, иных правовых актов или существа правоотношения."}]},{"n":"Статья 13","title":"Дееспособность несовершеннолетних в возрасте от четырнадцати до восемнадцати лет","sub":[{"n":"1","text":"Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет совершают сделки, за исключением названных в пункте 2 настоящей статьи, с письменного согласия своих законных представителей — родителей, усыновителей или попечителя."},{"n":"2","text":"Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет вправе самостоятельно, без согласия законных представителей:"},{"n":"1)","text":"распоряжаться своими заработком, стипендией и иными доходами;","lvl":1},{"n":"2)","text":"осуществлять права автора произведения науки, литературы или искусства, изобретения или иного охраняемого законом результата своей интеллектуальной деятельности;","lvl":1},{"n":"3)","text":"в соответствии с законом вносить вклады в кредитные организации и распоряжаться ими;","lvl":1},{"n":"4)","text":"совершать мелкие бытовые сделки и иные сделки, предусмотренные законом.","lvl":1},{"n":"3","text":"По достижении шестнадцати лет несовершеннолетние также вправе быть членами кооперативов в соответствии с законами о кооперативах."},{"n":"4","text":"Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет самостоятельно несут имущественную ответственность по сделкам, совершенным ими в соответствии с настоящей статьей."}]},{"n":"Статья 14","title":"Дееспособность малолетних в возрасте от шести до четырнадцати лет","sub":[{"n":"1","text":"За несовершеннолетних, не достигших четырнадцати лет (малолетних), сделки, за исключением указанных в пункте 2 настоящей статьи, могут совершать от их имени только их законные представители — родители, усыновители или опекуны."},{"n":"2","text":"Малолетние в возрасте от шести до четырнадцати лет вправе самостоятельно совершать:"},{"n":"1)","text":"мелкие бытовые сделки;","lvl":1},{"n":"2)","text":"сделки, направленные на безвозмездное получение выгоды, не требующие нотариального удостоверения либо государственной регистрации;","lvl":1},{"n":"3)","text":"сделки по распоряжению средствами, предоставленными законным представителем или с согласия последнего третьим лицом для определенной цели или для свободного распоряжения.","lvl":1},{"n":"3","text":"Имущественную ответственность по сделкам малолетнего, в том числе по сделкам, совершенным им самостоятельно, несут его законные представители, если не докажут, что обязательство было нарушено не по их вине."}]},{"n":"Статья 15","title":"Ограничение дееспособности гражданина","sub":[{"n":"1","text":"Гражданин, который вследствие пристрастия к азартным играм, злоупотребления спиртными напитками или наркотическими средствами ставит свою семью в тяжелое материальное положение, может быть ограничен судом в дееспособности в порядке, установленном гражданским процессуальным законодательством. Над ним устанавливается попечительство."},{"n":"2","text":"Он вправе самостоятельно совершать мелкие бытовые сделки. Совершать другие сделки, а также получать заработок, пенсию и иные доходы и распоряжаться ими он может лишь с согласия попечителя. Однако такой гражданин самостоятельно несет имущественную ответственность по совершенным им сделкам и за причиненный им вред."}]},{"n":"Статья 16","title":"Признание гражданина недееспособным","sub":[{"n":"1","text":"Гражданин, который вследствие психического расстройства не может понимать значения своих действий или руководить ими, может быть признан судом недееспособным в порядке, установленном гражданским процессуальным законодательством. Над ним устанавливается опека."},{"n":"2","text":"От имени гражданина, признанного недееспособным, сделки совершает его опекун, учитывая мнение такого гражданина, а при невозможности установления его мнения — с учетом информации о его предпочтениях, полученной от родителей такого гражданина, его прежних опекунов, иных лиц, оказывавших такому гражданину услуги и добросовестно исполнявших свои обязанности."}]},{"n":"Статья 17","title":"Опека и попечительство","sub":[{"n":"1","text":"Опека и попечительство устанавливаются для защиты прав и интересов недееспособных или не полностью дееспособных граждан. Опека и попечительство над несовершеннолетними устанавливаются также в целях их воспитания."},{"n":"2","text":"Опекуны являются представителями подопечных в силу закона и совершают от их имени и в их интересах все необходимые сделки."},{"n":"3","text":"Попечители дают согласие на совершение тех сделок, которые граждане, находящиеся под попечительством, не вправе совершать самостоятельно."},{"n":"4","text":"Опекуны и попечители обязаны заботиться о содержании своих подопечных, об обеспечении их уходом и лечением, защищать их права и интересы."}]},{"n":"Статья 18","title":"Признание гражданина безвестно отсутствующим","sub":[{"n":"1","text":"Гражданин может быть по заявлению заинтересованных лиц признан судом безвестно отсутствующим, если в течение года в месте его жительства нет сведений о месте его пребывания."},{"n":"2","text":"При невозможности установить день получения последних сведений об отсутствующем началом исчисления срока для признания безвестного отсутствия считается первое число месяца, следующего за тем, в котором были получены последние сведения об отсутствующем, а если невозможно установить этот месяц — первое января следующего года."},{"n":"3","text":"Имущество гражданина, признанного безвестно отсутствующим, при необходимости постоянного управления им передается на основании решения суда лицу, которое определяется органом опеки и попечительства и действует на основании договора о доверительном управлении, заключаемого с этим органом."}]},{"n":"Статья 19","title":"Объявление гражданина умершим","sub":[{"n":"1","text":"Гражданин может быть объявлен судом умершим, если в месте его жительства нет сведений о месте его пребывания в течение пяти лет, а если он пропал без вести при обстоятельствах, угрожавших смертью или дающих основание предполагать его гибель от определенного несчастного случая, — в течение шести месяцев."},{"n":"2","text":"Военнослужащий или иной гражданин, пропавший без вести в связи с военными действиями, может быть объявлен судом умершим не ранее чем по истечении двух лет со дня окончания военных действий."},{"n":"3","text":"Днем смерти гражданина, объявленного умершим, считается день вступления в законную силу решения суда об объявлении его умершим."}]},{"n":"Статья 20","title":"Понятие юридического лица","sub":[{"n":"1","text":"Юридическим лицом признается организация, которая имеет обособленное имущество и отвечает им по своим обязательствам, может от своего имени приобретать и осуществлять гражданские права, нести гражданские обязанности, быть истцом и ответчиком в суде."},{"n":"2","text":"Юридическое лицо должно быть зарегистрировано в едином государственном реестре юридических лиц в одной из организационно-правовых форм, предусмотренных законодательством."},{"n":"3","text":"Юридические лица, на имущество которых их участники имеют право собственности или иное вещное право, включают в себя государственные и муниципальные унитарные предприятия, а также учреждения."}]},{"n":"Статья 21","title":"Создание, реорганизация и ликвидация юридического лица","sub":[{"n":"1","text":"Юридическое лицо может быть создано по решению учредителей (участников) или органа юридического лица, уполномоченного на то учредительными документами."},{"n":"2","text":"Реорганизация юридического лица (слияние, присоединение, разделение, выделение, преобразование) может быть осуществлена по решению его учредителей (участников) либо органа юридического лица, уполномоченного на то учредительными документами."},{"n":"3","text":"При реорганизации юридического лица в форме присоединения к нему другого юридического лица первое из них считается реорганизованным с момента внесения в единый государственный реестр юридических лиц записи о прекращении присоединенного юридического лица."},{"n":"4","text":"Ликвидация юридического лица влечет его прекращение без перехода в порядке универсального правопреемства его прав и обязанностей к другим лицам."},{"n":"5","text":"Юридическое лицо может быть ликвидировано по решению его учредителей (участников) либо органа юридического лица, уполномоченного на то учредительными документами, в том числе в связи с истечением срока, на который создано юридическое лицо, с достижением цели, ради которой оно создано."}]},{"n":"Статья 22","title":"Ответственность юридического лица","sub":[{"n":"1","text":"Юридическое лицо отвечает по своим обязательствам всем принадлежащим ему имуществом."},{"n":"2","text":"Учредитель (участник) юридического лица или собственник его имущества не отвечает по обязательствам юридического лица, а юридическое лицо не отвечает по обязательствам учредителя (участника) или собственника, за исключением случаев, предусмотренных законом."}]},{"n":"Статья 23","title":"Филиалы и представительства","sub":[{"n":"1","text":"Представительством является обособленное подразделение юридического лица, расположенное вне места его нахождения, которое представляет интересы юридического лица и осуществляет их защиту."},{"n":"2","text":"Филиалом является обособленное подразделение юридического лица, расположенное вне места его нахождения и осуществляющее все его функции или их часть, в том числе функции представительства."},{"n":"3","text":"Представительства и филиалы не являются юридическими лицами. Они наделяются имуществом создавшим их юридическим лицом и действуют на основании утвержденных им положений."}]},{"n":"Статья 24","title":"Хозяйственные товарищества и общества","sub":[{"n":"1","text":"Хозяйственными товариществами и обществами признаются коммерческие организации с разделенным на доли (вклады) учредителей (участников) уставным (складочным) капиталом."},{"n":"2","text":"Хозяйственные товарищества могут создаваться в организационно-правовой форме полного товарищества или товарищества на вере (коммандитного товарищества)."},{"n":"3","text":"Хозяйственные общества могут создаваться в организационно-правовой форме акционерного общества или общества с ограниченной ответственностью."}]},{"n":"Статья 24.1","title":"Общество с ограниченной ответственностью","sub":[{"n":"1","text":"Обществом с ограниченной ответственностью признается созданное одним или несколькими лицами хозяйственное общество, уставный капитал которого разделен на доли."},{"n":"2","text":"Участники общества с ограниченной ответственностью не отвечают по его обязательствам и несут риск убытков, связанных с деятельностью общества, в пределах стоимости принадлежащих им долей."},{"n":"3","text":"Учредительным документом общества с ограниченной ответственностью является его устав, утвержденный учредителями."},{"n":"4","text":"Высшим органом общества является общее собрание участников. Исполнительный орган (директор, правление) осуществляет текущее руководство деятельностью общества и подотчетен общему собранию участников."},{"n":"5","text":"Участник вправе продать или иным образом уступить свою долю в уставном капитале общества другому участнику либо третьему лицу с соблюдением преимущественного права покупки других участников."},{"n":"6","text":"Участник вправе выйти из общества путем отчуждения своей доли обществу, если это предусмотрено уставом."}]},{"n":"Статья 24.2","title":"Акционерное общество","sub":[{"n":"1","text":"Акционерным обществом признается хозяйственное общество, уставный капитал которого разделен на определенное число акций."},{"n":"2","text":"Акционеры не отвечают по обязательствам общества и несут риск убытков, связанных с его деятельностью, в пределах стоимости принадлежащих им акций."},{"n":"3","text":"Высшим органом акционерного общества является общее собрание акционеров. В обществе с числом акционеров более пятидесяти создается совет директоров (наблюдательный совет)."},{"n":"4","text":"Акционерное общество может быть публичным (акции обращаются публично) или непубличным."},{"n":"5","text":"Акционерное общество вправе размещать дополнительно выпускаемые акции по решению общего собрания акционеров."}]},{"n":"Статья 24.3","title":"Производственный кооператив","sub":[{"n":"1","text":"Производственным кооперативом (артелью) признается добровольное объединение граждан на основе членства для совместной производственной или иной хозяйственной деятельности, основанной на их личном трудовом и ином участии и объединении его членами имущественных паевых взносов."},{"n":"2","text":"Члены производственного кооператива несут по обязательствам кооператива субсидиарную ответственность в размерах и в порядке, предусмотренных законом и уставом кооператива."},{"n":"3","text":"Высшим органом управления кооперативом является общее собрание его членов."}]},{"n":"Статья 24.4","title":"Унитарное предприятие","sub":[{"n":"1","text":"Унитарным предприятием признается коммерческая организация, не наделенная правом собственности на закрепленное за ней собственником имущество."},{"n":"2","text":"Имущество унитарного предприятия является неделимым и не может быть распределено по вкладам (долям, паям), в том числе между работниками предприятия."},{"n":"3","text":"Унитарное предприятие может быть государственным или муниципальным."}]},{"n":"Статья 24.5","title":"Некоммерческие организации","sub":[{"n":"1","text":"Некоммерческими организациями признаются юридические лица, не преследующие извлечение прибыли в качестве основной цели своей деятельности и не распределяющие полученную прибыль между участниками."},{"n":"2","text":"Некоммерческие организации могут создаваться в форме потребительских кооперативов, общественных организаций, ассоциаций (союзов), религиозных организаций, фондов, учреждений и в иных формах, предусмотренных законом."},{"n":"3","text":"Некоммерческие организации вправе осуществлять приносящую доход деятельность, если это предусмотрено их уставами, лишь постольку, поскольку это служит достижению целей, ради которых они созданы."}]},{"n":"Статья 24.6","title":"Решения собраний","sub":[{"n":"1","text":"Решение собрания — это решение участников гражданско-правового сообщества (участников общества, акционеров, членов кооператива, совладельцев и т.п.), принятое в установленном порядке и порождающее гражданско-правовые последствия для всех участников."},{"n":"2","text":"Решение собрания принимается большинством голосов участников, если иное не предусмотрено законом или уставом."},{"n":"3","text":"Решение собрания может быть оспорено в суде участником, не принимавшим участия в голосовании или голосовавшим против, если оно нарушает его права и принято с существенными нарушениями."},{"n":"4","text":"Решение собрания ничтожно, если принято по вопросу, не включенному в повестку, либо при отсутствии необходимого кворума, либо по вопросу, не относящемуся к компетенции собрания."}]},{"n":"Статья 24.7","title":"Корпоративный договор","sub":[{"n":"1","text":"Участники хозяйственного общества вправе заключить между собой корпоративный договор, регулирующий их права и обязанности по управлению обществом."},{"n":"2","text":"По корпоративному договору стороны обязуются голосовать определенным образом на общем собрании, согласованно осуществлять иные действия по управлению обществом, приобретать или отчуждать доли (акции) по определенной цене или при наступлении определенных обстоятельств."},{"n":"3","text":"Корпоративный договор заключается в письменной форме."},{"n":"4","text":"Нарушение корпоративного договора может повлечь признание недействительным решения органа общества, если все участники договора голосовали против него."}]},{"n":"Статья 25","title":"Дочерние и зависимые общества","sub":[{"n":"1","text":"Хозяйственное общество признается дочерним, если другое (основное) хозяйственное общество или товарищество в силу преобладающего участия в его уставном капитале либо в соответствии с заключенным между ними договором имеет возможность определять решения, принимаемые таким обществом."},{"n":"2","text":"Дочернее общество не отвечает по долгам основного общества. Основное общество, которое имеет право давать дочернему обществу обязательные для него указания, отвечает солидарно с дочерним обществом по сделкам, заключенным последним во исполнение таких указаний."},{"n":"3","text":"Хозяйственное общество признается зависимым, если другое (преобладающее, участвующее) общество имеет более двадцати процентов голосов в его уставном капитале."}]},{"n":"Статья 26","title":"Участие публичных образований в гражданских правоотношениях","sub":[{"n":"1","text":"Российская Федерация, субъекты Российской Федерации, а также городские, сельские поселения и другие муниципальные образования выступают в отношениях, регулируемых гражданским законодательством, на равных началах с иными участниками этих отношений — гражданами и юридическими лицами."},{"n":"2","text":"К субъектам гражданского права, указанным в пункте 1 настоящей статьи, применяются нормы, определяющие участие юридических лиц в отношениях, регулируемых гражданским законодательством, если иное не вытекает из закона или особенностей данных субъектов."},{"n":"3","text":"От имени публичных образований своими действиями могут приобретать и осуществлять гражданские права и обязанности органы государственной власти и органы местного самоуправления в рамках их компетенции."}]},{"n":"Статья 27","title":"Несостоятельность (банкротство)","sub":[{"n":"1","text":"Гражданин, который не в состоянии удовлетворить требования кредиторов по денежным обязательствам и (или) исполнить обязанность по уплате обязательных платежей, может быть признан несостоятельным (банкротом) по решению суда."},{"n":"2","text":"Основания и порядок признания гражданина или юридического лица несостоятельным (банкротом) устанавливаются законом о несостоятельности (банкротстве)."},{"n":"3","text":"С момента принятия решения о признании гражданина банкротом утрачивает силу его государственная регистрация в качестве индивидуального предпринимателя, а также аннулируются выданные ему лицензии на осуществление отдельных видов предпринимательской деятельности."},{"n":"4","text":"Основания и порядок признания бизнеса банкротом, очередность удовлетворения требований кредиторов и последствия банкротства определяются законом о несостоятельности (банкротстве)."}]},{"n":"Статья 27.1","title":"Банкротство бизнеса","sub":[{"n":"1","text":"Признание бизнеса (юридического лица или индивидуального предпринимателя) банкротом осуществляется судом в случае его неспособности удовлетворить требования кредиторов."},{"n":"2","text":"При банкротстве все обязательства бизнеса подлежат удовлетворению за счет его имущества в порядке очередности:"},{"n":"1)","text":"первая очередь — требования о возмещении вреда жизни и здоровью;","lvl":1},{"n":"2)","text":"вторая очередь — выходные пособия и оплата труда;","lvl":1},{"n":"3)","text":"третья очередь — расчеты с другими кредиторами.","lvl":1},{"n":"3","text":"Собственник бизнеса, признанного банкротом, утрачивает право распоряжаться его имуществом."},{"n":"4","text":"Ликвидация бизнеса осуществляется управляющим, назначаемым судом."}]},{"n":"Статья 28","title":"Коммерческие и некоммерческие организации","sub":[{"n":"1","text":"Юридическими лицами могут быть организации, преследующие извлечение прибыли в качестве основной цели своей деятельности (коммерческие организации) либо не имеющие извлечение прибыли в качестве такой цели и не распределяющие полученную прибыль между участниками (некоммерческие организации)."},{"n":"2","text":"Юридические лица, являющиеся коммерческими организациями, могут создаваться в организационно-правовых формах хозяйственных товариществ и обществ, крестьянских (фермерских) хозяйств, хозяйственных партнерств, производственных кооперативов, государственных и муниципальных унитарных предприятий."},{"n":"3","text":"Некоммерческие организации могут создаваться в форме потребительских кооперативов, общественных организаций, ассоциаций (союзов), религиозных организаций, фондов и учреждений."},{"n":"","text":"Глава 3.1. Предпринимательство и бизнес"}]},{"n":"Статья 28.1","title":"Понятие предпринимательской деятельности","sub":[{"n":"1","text":"Предпринимательской является самостоятельная, осуществляемая на свой риск деятельность, направленная на систематическое получение прибыли от пользования имуществом, продажи товаров, выполнения работ или оказания услуг."},{"n":"2","text":"Лица, осуществляющие предпринимательскую деятельность, должны быть зарегистрированы в этом качестве в установленном законом порядке."},{"n":"3","text":"Предпринимательская деятельность может осуществляться как индивидуальным предпринимателем, так и юридическим лицом."}]},{"n":"Статья 28.2","title":"Бизнес как имущественный комплекс","sub":[{"n":"1","text":"Бизнесом (делом) признается имущественный комплекс, используемый для систематического извлечения прибыли, включающий имущество, оборудование, права требования, долги, а также права на обозначения (название, вывеску, бренд)."},{"n":"2","text":"Бизнес может быть предметом купли-продажи, аренды, залога, доверительного управления, наследования."},{"n":"3","text":"При продаже бизнеса покупателю переходят все права и обязанности продавца, связанные с его деятельностью, если иное не предусмотрено договором."},{"n":"4","text":"Бизнес подлежит государственной регистрации в реестре предприятий."}]},{"n":"Статья 28.3","title":"Государственная регистрация бизнеса","sub":[{"n":"1","text":"Государственная регистрация бизнеса осуществляется уполномоченным органом (администрацией) путем внесения сведений в реестр предприятий."},{"n":"2","text":"Для регистрации бизнеса необходимы: заявление, устав (для юридического лица), сведения об учредителях, наименование и место нахождения."},{"n":"3","text":"С момента государственной регистрации бизнес приобретает правоспособность и может выступать в гражданском обороте."},{"n":"4","text":"Отказ в государственной регистрации допускается только по основаниям, установленным законом."}]},{"n":"Статья 28.4","title":"Лицензирование отдельных видов деятельности","sub":[{"n":"1","text":"Отдельные виды предпринимательской деятельности (торговля определенными товарами, добыча ресурсов, оказание услуг) осуществляются на основании лицензии — специального разрешения уполномоченного органа."},{"n":"2","text":"Перечень лицензируемых видов деятельности определяется законом."},{"n":"3","text":"Осуществление деятельности без лицензии, если она обязательна, влечет ответственность, установленную законом."},{"n":"4","text":"Лицензия может быть аннулирована в случае нарушения лицензионных требований."}]},{"n":"Статья 28.5","title":"Конкуренция и ограничение монополистической деятельности","sub":[{"n":"1","text":"Не допускается монополистическая деятельность, направленная на недопущение, ограничение или устранение конкуренции."},{"n":"2","text":"Запрещаются соглашения между хозяйствующими субъектами, которые приводят к установлению или поддержанию цен, разделу рынка, ограничению доступа на рынок других лиц."},{"n":"3","text":"Уполномоченный орган вправе применять меры по защите конкуренции, в том числе признавать недействительными соглашения и взыскивать полученный доход."}]},{"n":"Статья 28.6","title":"Защита прав потребителей","sub":[{"n":"1","text":"Потребителем признается гражданин, приобретающий или использующий товары (работы, услуги) исключительно для личных, семейных, домашних и иных нужд, не связанных с предпринимательской деятельностью."},{"n":"2","text":"Потребитель вправе требовать предоставления полной и достоверной информации о товаре (работе, услуге), его качестве, цене и условиях приобретения."},{"n":"3","text":"При нарушении прав потребителя он вправе требовать возмещения убытков, компенсации морального вреда, а также применения иных мер, предусмотренных законом."}]},{"n":"Статья 28.7","title":"Коммерческая тайна","sub":[{"n":"1","text":"Информация составляет коммерческую тайну, если она имеет действительную или потенциальную коммерческую ценность в силу неизвестности ее третьим лицам, к ней нет свободного доступа и обладатель принимает меры к охране ее конфиденциальности."},{"n":"2","text":"Лица, незаконными методами получившие информацию, составляющую коммерческую тайну, обязаны возместить причиненные убытки."},{"n":"3","text":"Режим коммерческой тайны устанавливается обладателем информации самостоятельно."}]},{"h":"Глава 4. Объекты гражданских прав"},{"n":"Статья 29","title":"Виды объектов","sub":[{"n":"1","text":"К объектам гражданских прав относятся вещи (включая наличные деньги и документарные ценные бумаги), иное имущество, в том числе безналичные денежные средства, бездокументарные ценные бумаги, цифровые права."},{"n":"2","text":"К объектам прав также относятся результаты работ и оказание услуг, охраняемые результаты интеллектуальной деятельности и приравненные к ним средства индивидуализации (интеллектуальная собственность)."},{"n":"3","text":"Нематериальные блага, такие как жизнь и здоровье, достоинство личности, личная неприкосновенность, честь и доброе имя, охраняются гражданским законодательством, если иное не вытекает из существа этих благ."}]},{"n":"Статья 30","title":"Недвижимые и движимые вещи","sub":[{"n":"1","text":"К недвижимым вещам (недвижимое имущество, недвижимость) относятся земельные участки, участки недр и все, что прочно связано с землей, то есть объекты, перемещение которых без несоразмерного ущерба их назначению невозможно, в том числе здания, сооружения, объекты незавершенного строительства."},{"n":"2","text":"К недвижимым вещам относятся также подлежащие государственной регистрации воздушные и морские суда, суда внутреннего плавания. Законом к недвижимым вещам может быть отнесено и иное имущество."},{"n":"3","text":"Вещи, не относящиеся к недвижимости, включая деньги и ценные бумаги, признаются движимым имуществом. Регистрация прав на движимые вещи не требуется, за исключением случаев, указанных в законе."}]},{"n":"Статья 31","title":"Предприятие как имущественный комплекс","sub":[{"n":"1","text":"Предприятием как объектом прав признается имущественный комплекс, используемый для осуществления предпринимательской деятельности."},{"n":"2","text":"Предприятие в целом как имущественный комплекс признается недвижимостью."},{"n":"3","text":"В состав предприятия как имущественного комплекса входят все виды имущества, предназначенные для его деятельности, включая земельные участки, здания, сооружения, оборудование, инвентарь, сырье, продукцию, права требования, долги, а также права на обозначения, индивидуализирующие предприятие, его продукцию, работы и услуги."}]},{"n":"Статья 32","title":"Плоды, продукция и доходы","sub":[{"n":"1","text":"Поступления, полученные в результате использования имущества (плоды, продукция, доходы), принадлежат лицу, использующему это имущество на законном основании, если иное не предусмотрено законом, иными правовыми актами или договором об использовании этого имущества."},{"n":"2","text":"Плоды, продукция и доходы, полученные арендатором в результате использования арендованного имущества в соответствии с договором, являются его собственностью."}]},{"n":"Статья 33","title":"Ценные бумаги","sub":[{"n":"1","text":"Ценной бумагой является документ, удостоверяющий с соблюдением установленной формы и обязательных реквизитов имущественные права, осуществление или передача которых возможны только при его предъявлении."},{"n":"2","text":"С передачей ценной бумаги переходят все удостоверяемые ею права в совокупности."},{"n":"3","text":"В случаях, предусмотренных законом, для осуществления и передачи прав, удостоверенных ценной бумагой, достаточно доказательств их закрепления в специальном реестре (обычном или компьютеризированном)."}]},{"n":"Статья 34","title":"Нематериальные блага и их защита","sub":[{"n":"1","text":"Нематериальные блага, принадлежащие гражданину от рождения или в силу закона, неотчуждаемы и непередаваемы иным способом."},{"n":"2","text":"В случаях и в порядке, предусмотренных законом, личные неимущественные права и другие нематериальные блага, принадлежавшие умершему, могут осуществляться и защищаться другими лицами, в том числе наследниками правообладателя."},{"n":"3","text":"Нематериальные блага защищаются в соответствии с настоящим Кодексом и другими законами в случаях и в порядке, ими предусмотренных, а также в тех случаях и пределах, в каких использование способов защиты гражданских прав вытекает из существа нарушенного нематериального блага или личного неимущественного права и характера последствий этого нарушения."}]},{"n":"Статья 35","title":"Животные","sub":[{"n":"1","text":"К животным применяются общие правила об имуществе постольку, поскольку законом или иными правовыми актами не установлено иное."},{"n":"2","text":"При осуществлении прав не допускается жестокое обращение с животными, противоречащее принципам гуманности."}]},{"n":"Статья 36","title":"Служебная и коммерческая тайна","sub":[{"n":"1","text":"Информация составляет служебную или коммерческую тайну в случае, когда информация имеет действительную или потенциальную коммерческую ценность в силу неизвестности ее третьим лицам, к ней нет свободного доступа на законном основании и обладатель информации принимает меры к охране ее конфиденциальности."},{"n":"2","text":"Сведения, которые не могут составлять служебную или коммерческую тайну, определяются законом и иными правовыми актами."},{"n":"3","text":"Лица, незаконными методами получившие информацию, которая составляет служебную или коммерческую тайну, обязаны возместить причиненные убытки."}]},{"h":"Глава 5. Сделки и представительство"},{"n":"Статья 37","title":"Понятие и формы сделок","sub":[{"n":"1","text":"Сделками признаются действия граждан и юридических лиц, направленные на установление, изменение или прекращение гражданских прав и обязанностей."},{"n":"2","text":"Сделки могут быть дву- или многосторонними (договоры), а также односторонними, для совершения которых необходимо и достаточно выражения воли одной стороны."},{"n":"3","text":"Сделки совершаются в устной или в письменной форме (простой или нотариальной). Сделка, для которой законом или соглашением сторон не установлена письменная форма, может быть совершена устно."}]},{"n":"Статья 38","title":"Недействительность сделок","sub":[{"n":"1","text":"Сделка недействительна по основаниям, установленным законом, в силу признания ее таковой судом (оспоримая сделка) либо независимо от такого признания (ничтожная сделка)."},{"n":"2","text":"Требование о признании оспоримой сделки недействительной может быть предъявлено стороной сделки или иным лицом, указанным в законе."},{"n":"3","text":"Недействительная сделка не влечет юридических последствий, за исключением тех, которые связаны с ее недействительностью, и недействительна с момента ее совершения."}]},{"n":"Статья 39","title":"Мнимые и притворные сделки","sub":[{"n":"1","text":"Мнимая сделка, то есть сделка, совершенная лишь для вида, без намерения создать соответствующие ей правовые последствия, ничтожна."},{"n":"2","text":"Притворная сделка, то есть сделка, которая совершена с целью прикрыть другую сделку, в том числе сделку на иных условиях, ничтожна. К сделке, которую стороны действительно имели в виду, с учетом существа и содержания сделки применяются относящиеся к ней правила."}]},{"n":"Статья 40","title":"Сделки с пороками воли","sub":[{"n":"1","text":"Сделка, совершенная под влиянием насилия или угрозы, может быть признана судом недействительной по иску потерпевшего."},{"n":"2","text":"Сделка, совершенная под влиянием обмана, может быть признана судом недействительной по иску потерпевшего. Обманом считается также намеренное умолчание об обстоятельствах, о которых лицо должно было сообщить при той добросовестности, какая от него требовалась по условиям оборота."},{"n":"3","text":"Сделка, совершенная под влиянием заблуждения, имеющего существенное значение, может быть признана судом недействительной по иску стороны, действовавшей под влиянием заблуждения."},{"n":"4","text":"Сделка, которую лицо было вынуждено совершить вследствие стечения тяжелых обстоятельств на крайне невыгодных для себя условиях, чем другая сторона воспользовалась (кабальная сделка), может быть признана судом недействительной по иску потерпевшего."}]},{"n":"Статья 41","title":"Недействительность сделки юридического лица, выходящей за пределы правоспособности","sub":[{"n":"1","text":"Сделка, совершенная юридическим лицом в противоречии с целями деятельности, определенно ограниченными в его учредительных документах, либо юридическим лицом, не имеющим лицензии на занятие соответствующей деятельностью, может быть признана судом недействительной по иску этого юридического лица, его учредителя (участника) или государственного органа, осуществляющего контроль за деятельностью юридического лица, если доказано, что другая сторона в сделке знала или должна была знать о ее незаконности."}]},{"n":"Статья 42","title":"Недействительность сделки, совершенной гражданином, не способным понимать значение своих действий","sub":[{"n":"1","text":"Сделка, совершенная гражданином, хотя и дееспособным, но находившимся в момент ее совершения в таком состоянии, когда он не был способен понимать значение своих действий или руководить ими, может быть признана судом недействительной по иску этого гражданина либо иных лиц, чьи права или охраняемые законом интересы нарушены в результате ее совершения."},{"n":"2","text":"Сделка, совершенная гражданином, впоследствии признанным недееспособным, может быть признана судом недействительной по иску его опекуна, если доказано, что в момент совершения сделки гражданин не был способен понимать значение своих действий или руководить ими."}]},{"n":"Статья 43","title":"Последствия недействительности сделок","sub":[{"n":"1","text":"При недействительности сделки каждая из сторон обязана возвратить другой все полученное по сделке, а в случае невозможности возвратить полученное в натуре (в том числе тогда, когда полученное выражается в пользовании имуществом, выполненной работе или предоставленной услуге) возместить его стоимость, если иные последствия недействительности сделки не предусмотрены законом."},{"n":"2","text":"Если из содержания оспоримой сделки вытекает, что она может быть лишь прекращена на будущее время, суд, признавая сделку недействительной, прекращает ее действие на будущее время."},{"n":"3","text":"Недействительность части сделки не влечет недействительности прочих ее частей, если можно предположить, что сделка была бы совершена и без включения недействительной ее части."}]},{"n":"Статья 44","title":"Сроки исковой давности по недействительным сделкам","sub":[{"n":"1","text":"Требование о признании оспоримой сделки недействительной и о применении последствий ее недействительности может быть предъявлено в течение одного года со дня прекращения насилия или угрозы, под влиянием которых была совершена сделка, либо со дня, когда истец узнал или должен был узнать об иных обстоятельствах, являющихся основанием для признания сделки недействительной."},{"n":"2","text":"Требование о применении последствий недействительности ничтожной сделки может быть предъявлено в течение трех лет со дня, когда началось ее исполнение."}]},{"n":"Статья 45","title":"Доверенность","sub":[{"n":"1","text":"Доверенностью признается письменное уполномочие, выдаваемое одним лицом другому лицу для представительства перед третьими лицами."},{"n":"2","text":"Доверенность на совершение сделок, требующих нотариальной формы, на подачу заявлений о государственной регистрации прав или сделок должна быть нотариально удостоверена, за исключением случаев, предусмотренных законом."},{"n":"3","text":"Письменное уполномочие на совершение сделки представителем может быть представлено представляемым непосредственно соответствующему третьему лицу."}]},{"n":"Статья 46","title":"Представительство","sub":[{"n":"1","text":"Представительством является совершение одним лицом (представителем) в силу имеющегося у него полномочия от имени другого лица (представляемого) сделок и иных юридических действий, в результате которых у представляемого возникают, изменяются и прекращаются гражданские права и обязанности."},{"n":"2","text":"Полномочие может также явствовать из обстановки, в которой действует представитель (продавец в розничной торговле, кассир и т.п.)."},{"n":"3","text":"Не являются представителями лица, действующие хотя и в чужих интересах, но от собственного имени (коммерческие посредники, конкурсные управляющие при банкротстве, душеприказчики при наследовании и т.п.), а также лица, уполномоченные на вступление в переговоры относительно возможных в будущем сделок."}]},{"n":"Статья 47","title":"Коммерческое представительство","sub":[{"n":"1","text":"Коммерческим представителем является лицо, постоянно и самостоятельно представительствующее от имени предпринимателей при заключении ими договоров в сфере предпринимательской деятельности."},{"n":"2","text":"Одновременное коммерческое представительство разных сторон в сделке допускается с согласия этих сторон, а также в других случаях, предусмотренных законом."},{"n":"3","text":"Особенности коммерческого представительства в отдельных сферах предпринимательской деятельности устанавливаются законом и иными правовыми актами."}]},{"n":"Статья 48","title":"Передоверие","sub":[{"n":"1","text":"Лицо, которому выдана доверенность, должно лично совершать те действия, на которые оно уполномочено. Оно может передоверить их совершение другому лицу, если уполномочено на это доверенностью либо вынуждено к этому силою обстоятельств для охраны интересов выдавшего доверенность."},{"n":"2","text":"Передавший полномочия другому лицу должен известить об этом выдавшего доверенность и сообщить ему необходимые сведения о лице, которому переданы полномочия. Неисполнение этой обязанности возлагает на передавшего полномочия ответственность за действия лица, которому он передал полномочия, как за свои собственные."}]},{"h":"Глава 6. Сроки и исковая давность"},{"n":"Статья 49","title":"Понятие исковой давности","sub":[{"n":"1","text":"Исковой давностью признается срок для защиты права по иску лица, право которого нарушено."},{"n":"2","text":"Защита нарушенного права осуществляется судом, арбитражным судом или третейским судом в соответствии с установленной подведомственностью."},{"n":"3","text":"Требование о защите нарушенного права принимается к рассмотрению судом независимо от истечения срока исковой давности, однако ее применение стороной в споре является основанием к вынесению решения об отказе в иске."}]},{"n":"Статья 50","title":"Сроки исковой давности","sub":[{"n":"1","text":"Общий срок исковой давности составляет три года со дня, определенного в соответствии с законодательством."},{"n":"2","text":"Течение срока исковой давности начинается со дня, когда лицо узнало или должно было узнать о нарушении своего права и о том, кто является надлежащим ответчиком по иску."},{"n":"3","text":"Для отдельных видов требований законом могут устанавливаться специальные сроки исковой давности, сокращенные или более длительные по сравнению с общим сроком."}]},{"n":"Статья 51","title":"Приостановление, перерыв и восстановление срока исковой давности","sub":[{"n":"1","text":"Течение срока исковой давности приостанавливается при наступлении обстоятельств, указанных в законе, в частности если предъявлению иска препятствовало чрезвычайное и непредотвратимое при данных условиях обстоятельство (непреодолимая сила)."},{"n":"2","text":"Течение срока исковой давности прерывается совершением обязанным лицом действий, свидетельствующих о признании долга. После перерыва течение срока исковой давности начинается заново."},{"n":"3","text":"В исключительных случаях, когда суд признает уважительной причину пропуска срока исковой давности по обстоятельствам, связанным с личностью истца, нарушенное право гражданина подлежит защите."}]},{"h":"Раздел II. Право собственности и другие вещные права"},{"h":"Глава 7. Содержание права собственности"},{"n":"Статья 52","title":"Содержание права собственности","sub":[{"n":"1","text":"Собственнику принадлежат права владения, пользования и распоряжения своим имуществом."},{"n":"2","text":"Собственник вправе по своему усмотрению совершать в отношении принадлежащего ему имущества любые действия, не противоречащие закону и иным правовым актам и не нарушающие права и охраняемые законом интересы других лиц."},{"n":"3","text":"Владение, пользование и распоряжение землей и другими природными ресурсами в той мере, в какой их оборот допускается законом, осуществляются их собственником свободно, если это не наносит ущерба окружающей среде."}]},{"n":"Статья 53","title":"Бремя содержания имущества и риск случайной гибели","sub":[{"n":"1","text":"Собственник несет бремя содержания принадлежащего ему имущества, если иное не предусмотрено законом или договором."},{"n":"2","text":"Риск случайной гибели или случайного повреждения имущества несет его собственник, если иное не предусмотрено законом или договором."},{"n":"3","text":"При утрате или повреждении имущества в результате действий третьих лиц собственник имеет право на полную компенсацию понесенных убытков в соответствии с действующими нормами."}]},{"n":"Статья 54","title":"Общая собственность","sub":[{"n":"1","text":"Имущество, находящееся в собственности двух или нескольких лиц, принадлежит им на праве общей собственности."},{"n":"2","text":"Имущество может находиться в общей собственности с определением доли каждого из собственников в праве собственности (долевая собственность) или без определения таких долей (совместная собственность)."},{"n":"3","text":"Общая собственность на имущество является долевой, за исключением случаев, когда законом предусмотрено образование совместной собственности на это имущество."},{"n":"4","text":"Участник долевой собственности вправе по своему усмотрению продать, подарить, завещать, отдать в залог свою долю либо распорядиться ею иным образом с соблюдением при ее возмездном отчуждении правил о преимущественном праве покупки."}]},{"n":"Статья 55","title":"Право собственности на землю","sub":[{"n":"1","text":"Граждане и юридические лица имеют право на равный доступ к приобретению земельных участков в собственность."},{"n":"2","text":"Земельные участки, находящиеся в государственной или муниципальной собственности, могут быть предоставлены в собственность граждан и юридических лиц, за исключением земельных участков, которые в соответствии с законом не могут находиться в частной собственности."},{"n":"3","text":"Собственник земельного участка вправе использовать по своему усмотрению все, что находится над и под поверхностью этого участка, если иное не предусмотрено законами о недрах, об использовании воздушного пространства, иными законами и не нарушает прав других лиц."}]},{"n":"Статья 56","title":"Право собственности на жилые помещения","sub":[{"n":"1","text":"Собственник жилого помещения осуществляет права владения, пользования и распоряжения принадлежащим ему на праве собственности жилым помещением в соответствии с его назначением и пределами его использования."},{"n":"2","text":"Собственник жилого помещения вправе предоставить во владение и (или) в пользование принадлежащее ему на праве собственности жилое помещение гражданину на основании договора найма, договора безвозмездного пользования или на ином законном основании."}]},{"n":"Статья 57","title":"Право хозяйственного ведения и оперативного управления","sub":[{"n":"1","text":"Государственное или муниципальное унитарное предприятие, которому имущество принадлежит на праве хозяйственного ведения, владеет, пользуется и распоряжается этим имуществом в пределах, определяемых в соответствии с законом."},{"n":"2","text":"Казенное предприятие и учреждение, за которыми имущество закреплено на праве оперативного управления, владеют, пользуются и распоряжаются этим имуществом в пределах, установленных законом, в соответствии с целями своей деятельности, заданиями собственника этого имущества и назначением этого имущества."}]},{"n":"Статья 58","title":"Право пожизненного наследуемого владения земельным участком","sub":[{"n":"1","text":"Гражданин, обладающий правом пожизненного наследуемого владения земельным участком, имеет права владения и пользования земельным участком, передаваемые по наследству."},{"n":"2","text":"Если из условий пользования земельным участком, установленных законом, не вытекает иное, владелец земельного участка вправе возводить на нем здания, сооружения и создавать другое недвижимое имущество, приобретая на него право собственности."}]},{"n":"Статья 59","title":"Сервитут","sub":[{"n":"1","text":"Сервитутом признается право ограниченного пользования чужим земельным участком (соседний участок) для прохода и проезда, прокладки и эксплуатации линий электропередачи, связи и трубопроводов, обеспечения водоснабжения и мелиорации, а также других нужд собственника недвижимого имущества, которые не могут быть обеспечены без установления сервитута."},{"n":"2","text":"Сервитут может устанавливаться по соглашению между лицом, требующим установления сервитута, и собственником соседнего участка. Сервитут подлежит государственной регистрации в порядке, установленном для регистрации прав на недвижимое имущество."},{"n":"3","text":"По требованию собственника земельного участка, обремененного сервитутом, сервитут может быть прекращен ввиду отпадения оснований, по которым он был установлен."},{"n":"4","text":"Публичный сервитут устанавливается законом или иным нормативным правовым актом в случаях, если это необходимо для обеспечения интересов государства, местного самоуправления или местного населения, без изъятия земельных участков."}]},{"h":"Глава 8. Приобретение и прекращение права собственности"},{"n":"Статья 60","title":"Момент возникновения права собственности","sub":[{"n":"1","text":"Право собственности у приобретателя вещи по договору возникает с момента ее передачи, если иное не предусмотрено законом или договором."},{"n":"2","text":"В случаях, когда отчуждение имущества подлежит государственной регистрации, право собственности у приобретателя возникает с момента такой регистрации, если иное не установлено законом."},{"n":"3","text":"Передачей признается вручение вещи приобретателю, а равно сдача перевозчику для отправки приобретателю или сдача в организацию связи для пересылки."}]},{"n":"Статья 61","title":"Приобретательная давность","sub":[{"n":"1","text":"Лицо — гражданин или юридическое лицо, — не являющееся собственником имущества, но добросовестно, открыто и непрерывно владеющее как своим собственным недвижимым имуществом в течение пятнадцати лет либо иным имуществом в течение пяти лет, приобретает право собственности на это имущество."},{"n":"2","text":"Право собственности на недвижимое и иное имущество, подлежащее государственной регистрации, возникает у лица, приобретшего это имущество в силу приобретательной давности, с момента такой регистрации."},{"n":"3","text":"До приобретения на имущество права собственности лицо, владеющее имуществом как своим собственным, имеет право на защиту своего владения против третьих лиц, не являющихся собственниками."}]},{"n":"Статья 62","title":"Прекращение права собственности","sub":[{"n":"1","text":"Право собственности прекращается при отчуждении собственником своего имущества другим лицам, отказе собственника от права собственности, гибели или уничтожении имущества и при утрате права собственности на имущество в иных случаях, предусмотренных законом."},{"n":"2","text":"Принудительное изъятие у собственника имущества не допускается, кроме случаев, когда по основаниям, предусмотренным законом, производятся обращение взыскания на имущество по обязательствам, отчуждение имущества, которое в силу закона не может принадлежать данному лицу, и другие случаи."}]},{"h":"Глава 9. Защита вещных прав"},{"n":"Статья 63","title":"Истребование имущества из чужого незаконного владения (Виндикация)","sub":[{"n":"1","text":"Собственник вправе истребовать свое имущество из чужого незаконного владения."},{"n":"2","text":"Если имущество возмездно приобретено у лица, которое не имело права его отчуждать, о чем приобретатель не знал и не мог знать (добросовестный приобретатель), собственник вправе истребовать это имущество в случае, когда оно утеряно собственником или лицом, которому имущество было передано, либо похищено у того или другого, либо выбыло из их владения иным путем помимо их воли."},{"n":"3","text":"Истребование имущества по основаниям, указанным в пункте 2 настоящей статьи, не допускается, если имущество было продано в порядке, установленном для исполнения судебных актов."}]},{"n":"Статья 64","title":"Защита прав собственника от нарушений, не связанных с лишением владения (Негаторный иск)","sub":[{"n":"1","text":"Собственник может требовать устранения всяких нарушений его права, хотя бы эти нарушения и не были соединены с лишением владения."},{"n":"2","text":"Требование об устранении нарушений может содержать просьбу об запрете совершения определенных действий, создающих угрозу нарушения права собственности."},{"n":"3","text":"Права, предусмотренные настоящей статьей, принадлежат также лицу, хотя и не являющемуся собственником, но владеющему имуществом на праве пожизненного наследуемого владения, хозяйственного ведения, оперативного управления либо по иному основанию."}]},{"n":"Статья 65","title":"Признание права собственности","sub":[{"n":"1","text":"Собственник вправе требовать признания своего права собственности в судебном порядке, если это право оспаривается или нарушается другим лицом."},{"n":"2","text":"Иск о признании права собственности может быть предъявлен как в отношении недвижимого, так и в отношении движимого имущества."},{"n":"3","text":"В случае удовлетворения иска о признании права собственности суд подтверждает наличие у истца соответствующего права, что является основанием для государственной регистрации права, если имущество подлежит такой регистрации."}]},{"n":"Статья 66","title":"Самозащита гражданских прав","sub":[{"n":"1","text":"Допускается самозащита гражданских прав."},{"n":"2","text":"Способы самозащиты должны быть соразмерны нарушению и не выходить за пределы действий, необходимых для его пресечения."}]},{"h":"Раздел III. Общая часть обязательственного права"},{"h":"Глава 10. Понятие и исполнение обязательств"},{"n":"Статья 67","title":"Понятие обязательства","sub":[{"n":"1","text":"В силу обязательства одно лицо (должник) обязано совершить в пользу другого лица (кредитора) определенное действие, как то: передать имущество, выполнить работу, оказать услугу, внести вклад, уплатить деньги либо воздержаться от определенного действия, а кредитор имеет право требовать от должника исполнения его обязанности."},{"n":"2","text":"Обязательства возникают из договоров и иных сделок, вследствие причинения вреда, вследствие неосновательного обогащения, а также из иных оснований, указанных в законе."},{"n":"3","text":"При установлении, исполнении обязательства и после его прекращения стороны обязаны действовать добросовестно, учитывая права и законные интересы друг друга."}]},{"n":"Статья 68","title":"Надлежащее исполнение обязательств","sub":[{"n":"1","text":"Обязательства должны исполняться надлежащим образом в соответствии с условиями обязательства и требованиями закона, иных правовых актов, а при отсутствии таких условий и требований — в соответствии с обычаями или иными обычно предъявляемыми требованиями."},{"n":"2","text":"Односторонний отказ от исполнения обязательства и одностороннее изменение его условий не допускаются, за исключением случаев, предусмотренных законом или договором."},{"n":"3","text":"Если обязательство предусматривает или позволяет определить день его исполнения или период времени, в течение которого оно должно быть исполнено, обязательство подлежит исполнению в этот день или в любой момент в пределах такого периода."}]},{"n":"Статья 69","title":"Множественность лиц в обязательстве","sub":[{"n":"1","text":"В обязательстве могут участвовать несколько кредиторов или несколько должников."},{"n":"2","text":"Если каждый из кредиторов вправе требовать исполнения, а каждый из должников обязан исполнить обязательство в равной доле с другими, такое обязательство является долевым."},{"n":"3","text":"Если кредитор вправе требовать исполнения, а должник обязан исполнить обязательство полностью, такое обязательство является солидарным."}]},{"n":"Статья 70","title":"Перемена лиц в обязательстве","sub":[{"n":"1","text":"Перемена лиц в обязательстве осуществляется на основании сделки (уступка требования, перевод долга) или на основании закона."},{"n":"2","text":"Уступка требования кредитором другому лицу допускается, если она не противоречит закону, иным правовым актам или договору."},{"n":"3","text":"Перевод должником своего долга на другое лицо допускается с согласия кредитора и при отсутствии такого согласия является ничтожным."}]},{"n":"Статья 71","title":"Прекращение обязательств","sub":[{"n":"1","text":"Обязательство прекращается полностью или частично по основаниям, предусмотренным настоящим Кодексом, другими законами, иными правовыми актами или договором."},{"n":"2","text":"Надлежащее исполнение прекращает обязательство."},{"n":"3","text":"Обязательство прекращается зачетом встречного однородного требования, срок которого наступил либо срок которого не указан или определен моментом востребования."},{"n":"4","text":"Обязательство прекращается невозможностью исполнения, если она вызвана наступившим после возникновения обязательства обстоятельством, за которое ни одна из сторон не отвечает."},{"n":"5","text":"Обязательство прекращается освобождением кредитором должника от лежащих на нем обязанностей (прощение долга), если это не нарушает прав других лиц в отношении имущества кредитора."}]},{"h":"Глава 11. Договорные обязательства"},{"n":"Статья 72","title":"Понятие и условия договора","sub":[{"n":"1","text":"Договором признается соглашение двух или нескольких лиц об установлении, изменении или прекращении гражданских прав и обязанностей."},{"n":"2","text":"Граждане и юридические лица свободны в заключении договора. Понуждение к заключению договора не допускается, за исключением случаев, когда обязанность заключить договор предусмотрена законом или добровольно принятым обязательством."},{"n":"3","text":"Условия договора определяются по усмотрению сторон, кроме случаев, когда содержание соответствующего условия предписано законом или иными правовыми актами."},{"n":"4","text":"Договор должен соответствовать обязательным для сторон правилам, установленным законом и иными правовыми актами, действующими в момент его заключения."}]},{"n":"Статья 73","title":"Существенные условия договора","sub":[{"n":"1","text":"Существенными условиями договора являются условия о предмете договора, условия, которые названы в законе или иных правовых актах как существенные или необходимые для договоров данного вида, а также все те условия, относительно которых по заявлению одной из сторон должно быть достигнуто соглашение."},{"n":"2","text":"Договор считается заключенным, если между сторонами в требуемой в подлежащих случаях форме достигнуто соглашение по всем существенным условиям договора."}]},{"n":"Статья 74","title":"Толкование договора","sub":[{"n":"1","text":"При толковании условий договора судом принимается во внимание буквальное значение содержащихся в нем слов и выражений. Буквальное значение условия договора в случае его неясности устанавливается путем сопоставления с другими условиями и смыслом договора в целом."},{"n":"2","text":"Если правила, содержащиеся в части первой настоящей статьи, не позволяют определить содержание договора, должна быть выяснена действительная общая воля сторон с учетом цели договора. При этом принимаются во внимание все соответствующие обстоятельства, включая предшествующие договору переговоры и переписку, практику, установившуюся во взаимных отношениях сторон, обычаи, последующее поведение сторон."}]},{"n":"Статья 75","title":"Публичный договор","sub":[{"n":"1","text":"Публичным договором признается договор, заключенный коммерческой организацией и устанавливающий ее обязанности по продаже товаров, выполнению работ или оказанию услуг, которые такая организация по характеру своей деятельности должна осуществлять в отношении каждого, кто к ней обратится (розничная торговля, перевозка транспортом общего пользования, услуги связи, энергоснабжение, медицинское, гостиничное обслуживание и т.п.)."},{"n":"2","text":"Коммерческая организация не вправе оказывать предпочтение одному лицу перед другим в отношении заключения публичного договора, кроме случаев, предусмотренных законом и иными правовыми актами."},{"n":"3","text":"Цена товаров, работ и услуг, а также иные условия публичного договора устанавливаются одинаковыми для всех потребителей, за исключением случаев, когда законом и иными правовыми актами допускается предоставление льгот для отдельных категорий потребителей."}]},{"n":"Статья 76","title":"Договор присоединения","sub":[{"n":"1","text":"Договором присоединения признается договор, условия которого определены одной из сторон в формулярах или иных стандартных формах и могли быть приняты другой стороной не иначе как путем присоединения к предложенному договору в целом."},{"n":"2","text":"Присоединившаяся к договору сторона вправе потребовать расторжения или изменения договора, если договор присоединения хотя и не противоречит закону и иным правовым актам, но лишает эту сторону прав, обычно предоставляемых по договорам такого вида, исключает или ограничивает ответственность другой стороны за нарушение обязательств либо содержит другие явно обременительные для присоединившейся стороны условия, которые она исходя из своих разумно понимаемых интересов не приняла бы при наличии у нее возможности участвовать в определении условий договора."}]},{"n":"Статья 77","title":"Предварительный договор","sub":[{"n":"1","text":"По предварительному договору стороны обязуются заключить в будущем договор о передаче имущества, выполнении работ или оказании услуг (основной договор) на условиях, предусмотренных предварительным договором."},{"n":"2","text":"Предварительный договор заключается в форме, установленной для основного договора, а если форма основного договора не установлена, то в письменной форме. Несоблюдение правил о форме предварительного договора влечет его ничтожность."},{"n":"3","text":"Предварительный договор должен содержать условия, позволяющие установить предмет, а также другие существенные условия основного договора."}]},{"n":"Статья 78","title":"Заключение договора (Оферта и акцепт)","sub":[{"n":"1","text":"Офертой признается адресованное одному или нескольким конкретным лицам предложение, которое достаточно определенно и выражает намерение лица, сделавшего предложение, считать себя заключившим договор с адресатом, которым будет принято предложение."},{"n":"2","text":"Акцептом признается ответ лица, которому адресована оферта, о ее принятии. Акцепт должен быть полным и безоговорочным."},{"n":"3","text":"Договор признается заключенным в момент получения лицом, направившим оферту, ее акцепта."},{"n":"4","text":"Молчание не является акцептом, если иное не вытекает из закона, обычая или из прежних деловых отношений сторон."}]},{"n":"Статья 79","title":"Изменение и расторжение договора","sub":[{"n":"1","text":"Изменение и расторжение договора возможны по соглашению сторон, если иное не предусмотрено настоящим Кодексом, другими законами или договором."},{"n":"2","text":"По требованию одной из сторон договор может быть изменен или расторгнут по решению суда только:"},{"n":"1)","text":"при существенном нарушении договора другой стороной;","lvl":1},{"n":"2)","text":"в иных случаях, предусмотренных настоящим Кодексом, другими законами или договором.","lvl":1},{"n":"3","text":"Существенным признается нарушение договора одной из сторон, которое влечет для другой стороны такой ущерб, что она в значительной степени лишается того, на что была вправе рассчитывать при заключении договора."},{"n":"4","text":"Сторона, которой настоящим Кодексом, другими законами или договором предоставлено право на односторонний отказ от исполнения договора, должна при осуществлении этого права действовать добросовестно и разумно в пределах, предусмотренных настоящим Кодексом, другими законами или договором."}]},{"h":"Глава 12. Обеспечение исполнения обязательств"},{"n":"Статья 80","title":"Способы обеспечения исполнения обязательств","sub":[{"n":"1","text":"Исполнение обязательств может обеспечиваться неустойкой, залогом, удержанием вещи должника, поручительством, независимой гарантией, задатком, обеспечительным платежом и другими способами, предусмотренными законом или договором."},{"n":"2","text":"Недействительность соглашения об обеспечении исполнения обязательства не влечет недействительности основного обязательства (основного долга)."},{"n":"3","text":"Недействительность основного обязательства влечет недействительность обеспечивающего его обязательства, если иное не установлено законом."}]},{"n":"Статья 81","title":"Неустойка","sub":[{"n":"1","text":"Неустойкой (штрафом, пеней) признается определенная законом или договором денежная сумма, которую должник обязан уплатить кредитору в случае неисполнения или ненадлежащего исполнения обязательства, в частности в случае просрочки исполнения."},{"n":"2","text":"По требованию об уплате неустойки кредитор не обязан доказывать причинение ему убытков."},{"n":"3","text":"Соглашение о неустойке должно быть совершено в письменной форме независимо от формы основного обязательства. Несоблюдение письменной формы влечет недействительность соглашения о неустойке."}]},{"n":"Статья 82","title":"Залог","sub":[{"n":"1","text":"В силу залога кредитор по обеспеченному залогом обязательству (залогодержатель) имеет право в случае неисполнения или ненадлежащего исполнения должником этого обязательства получить удовлетворение из стоимости заложенного имущества преимущественно перед другими кредиторами лица, которому принадлежит это имущество."},{"n":"2","text":"Залог возникает в силу договора или на основании закона при наступлении указанных в нем обстоятельств, если закон предусматривает, какое имущество и для обеспечения исполнения какого обязательства признается находящимся в залоге."},{"n":"3","text":"Залогодателем может быть как сам должник, так и третье лицо, не участвующее в основном обязательстве."}]},{"n":"Статья 83","title":"Удержание вещи","sub":[{"n":"1","text":"Кредитор, у которого находится вещь, подлежащая передаче должнику либо лицу, указанному должником, вправе в случае неисполнения должником в срок обязательства по оплате этой вещи или возмещению кредитору связанных с нею издержек и других убытков удерживать ее до тех пор, пока соответствующее обязательство не будет исполнено."},{"n":"2","text":"Кредитор может удерживать находящуюся у него вещь, несмотря на то, что после того, как вещь поступила во владение кредитора, права на нее приобретены третьим лицом."}]},{"n":"Статья 84","title":"Поручительство","sub":[{"n":"1","text":"По договору поручительства поручитель обязывается перед кредитором другого лица отвечать за исполнение последним его обязательства полностью или в части."},{"n":"2","text":"Договор поручительства должен быть совершен в письменной форме. Несоблюдение письменной формы влечет недействительность договора поручительства."},{"n":"3","text":"При неисполнении или ненадлежащем исполнении должником обеспеченного поручительством обязательства поручитель и должник отвечают перед кредитором солидарно, если законом или договором поручительства не предусмотрена субсидиарная ответственность поручителя."}]},{"n":"Статья 85","title":"Независимая гарантия","sub":[{"n":"1","text":"В силу независимой гарантии гарант принимает на себя по просьбе другого лица (принципала) обязательство уплатить указанному им третьему лицу (бенефициару) определенную денежную сумму в соответствии с условиями данного гарантом обязательства независимо от действительности обеспечиваемого такой гарантией обязательства."},{"n":"2","text":"Независимая гарантия выдается в письменной форме, позволяющей достоверно определить условия гарантии и удостовериться в подлинности ее выдачи."}]},{"n":"Статья 86","title":"Задаток","sub":[{"n":"1","text":"Задатком признается денежная сумма, выдаваемая одной из договаривающихся сторон в счет причитающихся с нее по договору платежей другой стороне, в доказательство заключения договора и в обеспечение его исполнения."},{"n":"2","text":"Соглашение о задатке независимо от суммы задатка должно быть совершено в письменной форме."},{"n":"3","text":"Если обязательство прекращается до начала его исполнения по соглашению сторон либо вследствие невозможности исполнения, задаток должен быть возвращен."},{"n":"4","text":"Если за неисполнение договора ответственна сторона, давшая задаток, он остается у другой стороны. Если за неисполнение договора ответственна сторона, получившая задаток, она обязана уплатить другой стороне двойную сумму задатка."}]},{"n":"Статья 87","title":"Обеспечительный платеж","sub":[{"n":"1","text":"Денежное обязательство может быть обеспечено обеспечительным платежом — денежной суммой, вносимой одной из сторон в пользу другой стороны в счет причитающихся с нее платежей по договору."},{"n":"2","text":"В случае нарушения обязательства, обеспеченного обеспечительным платежом, другая сторона вправе зачесть сумму обеспечительного платежа в счет исполнения нарушенного обязательства."}]},{"h":"Глава 13. Ответственность за нарушение обязательств"},{"n":"Статья 88","title":"Обязанность должника возместить убытки","sub":[{"n":"1","text":"Должник обязан возместить кредитору убытки, причиненные неисполнением или ненадлежащим исполнением обязательства."},{"n":"2","text":"Убытки определяются в соответствии с правилами, предусмотренными законом. Под убытками понимаются расходы, которые лицо, чье право нарушено, произвело или должно будет произвести для восстановления нарушенного права (реальный ущерб), а также неполученные доходы (упущенная выгода)."},{"n":"3","text":"При определении упущенной выгоды учитываются предпринятые кредитором для ее получения меры и сделанные с этой целью приготовления."}]},{"n":"Статья 89","title":"Ответственность за нарушение обязательства","sub":[{"n":"1","text":"Лицо, не исполнившее обязательство или исполнившее его ненадлежащим образом, несет ответственность при наличии вины (умысла или неосторожности), кроме случаев, когда законом или договором предусмотрены иные основания ответственности."},{"n":"2","text":"Лицо признается невиновным, если при той степени заботливости и осмотрительности, какая от него требовалась по характеру обязательства и условиям оборота, оно приняло все меры для надлежащего исполнения обязательства."},{"n":"3","text":"Отсутствие вины доказывается лицом, нарушившим обязательство."}]},{"n":"Статья 90","title":"Ответственность за неисполнение денежного обязательства","sub":[{"n":"1","text":"В случае неисполнения или ненадлежащего исполнения денежного обязательства должник обязан уплатить кредитору проценты на сумму этих средств."},{"n":"2","text":"Размер процентов определяется ключевой ставкой Банка России, действовавшей в соответствующие периоды, если иной размер процентов не установлен законом или договором."},{"n":"3","text":"Проценты за пользование чужими средствами взимаются по день уплаты суммы этих средств кредитору, если законом, иными правовыми актами или договором не установлен для начисления процентов более короткий срок."}]},{"h":"Часть вторая"},{"h":"Раздел IV. Отдельные виды обязательств"},{"h":"Глава 14. Купля-продажа"},{"n":"Статья 91","title":"Договор купли-продажи","sub":[{"n":"1","text":"По договору купли-продажи одна сторона (продавец) обязуется передать вещь (товар) в собственность другой стороне (покупателю), а покупатель обязуется принять этот товар и уплатить за него определенную денежную сумму (цену)."},{"n":"2","text":"К купле-продаже ценных бумаг и валютных ценностей применяются общие положения о купле-продаже, если законом не установлены специальные правила их купли-продажи."},{"n":"3","text":"Условие договора купли-продажи о товаре считается согласованным, если договор позволяет определить наименование и количество товара."}]},{"n":"Статья 92","title":"Договор розничной купли-продажи","sub":[{"n":"1","text":"По договору розничной купли-продажи продавец, осуществляющий предпринимательскую деятельность по продаже товаров в розницу, обязуется передать покупателю товар, предназначенный для личного, семейного, домашнего или иного использования, не связанного с предпринимательской деятельностью."},{"n":"2","text":"Договор розничной купли-продажи является публичным договором."},{"n":"3","text":"К отношениям по договору розничной купли-продажи с участием покупателя-гражданина применяются законы о защите прав потребителей и иные правовые акты, принятые в соответствии с ними."}]},{"n":"Статья 93","title":"Договор поставки","sub":[{"n":"1","text":"По договору поставки поставщик-продавец, осуществляющий предпринимательскую деятельность, обязуется передать в обусловленный срок или сроки производимые или закупаемые им товары покупателю для использования в предпринимательской деятельности или в иных целях, не связанных с личным использованием."},{"n":"2","text":"Поставка товаров осуществляется путем отгрузки (передачи) товаров покупателю, являющемуся стороной договора поставки, или лицу, указанному в договоре в качестве получателя."},{"n":"3","text":"Покупатель оплачивает поставляемые товары с соблюдением порядка и формы расчетов, предусмотренных договором поставки."}]},{"n":"Статья 94","title":"Договор продажи недвижимости","sub":[{"n":"1","text":"По договору продажи недвижимости продавец обязуется передать в собственность покупателя земельный участок, здание, сооружение, квартиру или другое недвижимое имущество."},{"n":"2","text":"Договор продажи недвижимости заключается в письменной форме путем составления одного документа, подписанного сторонами. Несоблюдение формы договора продажи недвижимости влечет его недействительность."},{"n":"3","text":"Переход права собственности на недвижимость по договору продажи недвижимости к покупателю подлежит государственной регистрации."}]},{"n":"Статья 95","title":"Договор продажи предприятия","sub":[{"n":"1","text":"По договору продажи предприятия продавец обязуется передать в собственность покупателя предприятие в целом как имущественный комплекс, за исключением прав и обязанностей, которые продавец не вправе передавать другим лицам."},{"n":"2","text":"Договор продажи предприятия заключается в письменной форме путем составления одного документа, подписанного сторонами, с обязательным приложением к нему документов, указанных в законе."},{"n":"3","text":"Договор продажи предприятия подлежит государственной регистрации и считается заключенным с момента такой регистрации."}]},{"h":"Глава 15. Дарение и Мена"},{"n":"Статья 96","title":"Договор мены","sub":[{"n":"1","text":"По договору мены каждая из сторон обязуется передать в собственность другой стороны один товар в обмен на другой."},{"n":"2","text":"К договору мены применяются соответственно правила о купле-продаже, если это не противоречит существу мены. При этом каждая из сторон признается продавцом товара, который она обязуется передать, и покупателем товара, который она обязуется принять в обмен."},{"n":"3","text":"Если из договора мены не вытекает иное, товары, подлежащие обмену, предполагаются равноценными, а расходы на их передачу и принятие осуществляются в каждом случае той стороной, которая несет соответствующие обязанности."}]},{"n":"Статья 97","title":"Договор дарения","sub":[{"n":"1","text":"По договору дарения одна сторона (даритель) безвозмездно передает или обязуется передать другой стороне (одаряемому) вещь в собственность либо имущественное право (требование) к себе или к третьему лицу либо освобождает или обязуется освободить ее от имущественной обязанности перед собой или перед третьим лицом."},{"n":"2","text":"При наличии встречной передачи вещи или права либо встречного обязательства договор не признается дарением. К такому договору применяются правила, предусмотренные законодательством для соответствующего типа сделок."},{"n":"3","text":"Обещание безвозмездно передать кому-либо вещь или имущественное право признается договором дарения и связывает обещавшего, если обещание сделано в надлежащей форме и содержит ясно выраженное намерение совершить дарение в будущем."}]},{"n":"Статья 98","title":"Пожертвование","sub":[{"n":"1","text":"Пожертвованием признается дарение вещи или права в общеполезных целях. Пожертвования могут делаться гражданам, медицинским, образовательным организациям, организациям социального обслуживания и другим аналогичным организациям, благотворительным и научным организациям, фондам, музеям и другим учреждениям культуры, общественным и религиозным организациям, а также государству и другим субъектам гражданского права."},{"n":"2","text":"На принятие пожертвования не требуется чьего-либо разрешения или согласия."},{"n":"3","text":"Пожертвование имущества гражданину должно быть, а юридическим лицам может быть обусловлено жертвователем использованием этого имущества по определенному назначению."}]},{"h":"Глава 16. Аренда и Наем жилого помещения"},{"n":"Статья 99","title":"Договор аренды","sub":[{"n":"1","text":"По договору аренды (имущественного найма) арендодатель (наймодатель) обязуется предоставить арендатору (нанимателю) имущество за плату во временное владение и пользование или во временное пользование."},{"n":"2","text":"Плоды, продукция и доходы, полученные арендатором в результате использования арендованного имущества в соответствии с договором, являются его собственностью."},{"n":"3","text":"В аренду могут быть переданы земельные участки и другие обособленные природные объекты, предприятия и другие имущественные комплексы, здания, сооружения, оборудование, транспортные средства и другие вещи, которые не теряют своих натуральных свойств в процессе их использования (непотребляемые вещи)."}]},{"n":"Статья 100","title":"Договор проката","sub":[{"n":"1","text":"По договору проката арендодатель, осуществляющий сдачу имущества в аренду в качестве постоянной предпринимательской деятельности, обязуется предоставить арендатору движимое имущество за плату во временное владение и пользование."},{"n":"2","text":"Договор проката заключается в письменной форме."},{"n":"3","text":"Имущество, предоставленное по договору проката, используется для потребительских целей, если иное не предусмотрено договором."}]},{"n":"Статья 101","title":"Договор аренды транспортного средства","sub":[{"n":"1","text":"По договору аренды транспортного средства арендодатель предоставляет арендатору транспортное средство за плату во временное владение и пользование."},{"n":"2","text":"Аренда транспортного средства может осуществляться с предоставлением услуг по управлению и технической эксплуатации (аренда с экипажем) или без предоставления таких услуг (аренда без экипажа)."},{"n":"3","text":"Арендатор обязан поддерживать надлежащее состояние арендованного транспортного средства и производить за свой счет текущий и капитальный ремонт."}]},{"n":"Статья 102","title":"Договор финансовой аренды (Лизинг)","sub":[{"n":"1","text":"По договору финансовой аренды (договору лизинга) арендодатель обязуется приобрести в собственность указанное арендатором имущество у определенного им продавца и предоставить арендатору это имущество за плату во временное владение и пользование."},{"n":"2","text":"Договор лизинга может быть заключен на срок, равный сроку полезного использования имущества или меньший."},{"n":"3","text":"Арендатор вправе предъявить непосредственно продавцу имущества требования, вытекающие из договора купли-продажи, заключенного между продавцом и арендодателем."}]},{"n":"Статья 103","title":"Договор безвозмездного пользования (Ссуда)","sub":[{"n":"1","text":"По договору безвозмездного пользования (договору ссуды) одна сторона (ссудодатель) обязуется передать или передает вещь в безвозмездное временное пользование другой стороне (ссудополучателю), а последняя обязуется вернуть ту же вещь в том состоянии, в каком она ее получила, с учетом нормального износа."},{"n":"2","text":"Договор ссуды заключается в письменной форме, если сторонами являются граждане и стоимость передаваемой вещи превышает десять тысяч рублей."}]},{"n":"Статья 104","title":"Договор найма жилого помещения","sub":[{"n":"1","text":"По договору найма жилого помещения одна сторона - собственник жилого помещения или уполномоченное им лицо (наймодатель) - обязуется предоставить другой стороне (гражданину - нанимателю) жилое помещение за плату во владение и пользование для проживания в нем."},{"n":"2","text":"Юридическим лицам жилое помещение может быть предоставлено во владение и (или) пользование на основе договора аренды или иного договора. Юридическое лицо может использовать жилое помещение только для проживания граждан."},{"n":"3","text":"Объект договора найма жилого помещения должен быть изолированным и пригодным для постоянного проживания."}]},{"h":"Глава 17. Подряд и Возмездное оказание услуг"},{"n":"Статья 105","title":"Договор подряда","sub":[{"n":"1","text":"По договору подряда одна сторона (подрядчик) обязуется выполнить по заданию другой стороны (заказчика) определенную работу и сдать ее результат заказчику, а заказчик обязуется принять результат работы и оплатить его."},{"n":"2","text":"Если иное не предусмотрено договором, работа выполняется иждивением подрядчика — из его материалов, его силами и средствами."},{"n":"3","text":"Подрядчик несет ответственность за ненадлежащее качество предоставленных им материалов и оборудования, а также за предоставление материалов и оборудования, обремененных правами третьих лиц."}]},{"n":"Статья 106","title":"Бытовой подряд","sub":[{"n":"1","text":"По договору бытового подряда подрядчик, осуществляющий соответствующую предпринимательскую деятельность, обязуется выполнить по заданию гражданина (заказчика) определенную работу, предназначенную удовлетворять бытовые или другие личные потребности заказчика, а заказчик обязуется принять и оплатить работу."},{"n":"2","text":"Договор бытового подряда является публичным договором."},{"n":"3","text":"К отношениям по договору бытового подряда с участием заказчика-гражданина применяются законы о защите прав потребителей и иные правовые акты, принятые в соответствии с ними."}]},{"n":"Статья 107","title":"Договор строительного подряда","sub":[{"n":"1","text":"По договору строительного подряда подрядчик обязуется в установленный договором срок построить по заданию заказчика определенный объект либо выполнить иные строительные работы, а заказчик обязуется создать подрядчику необходимые условия для выполнения работ, принять их результат и уплатить обусловленную цену."},{"n":"2","text":"Договор строительного подряда заключается на строительство или реконструкцию предприятия, здания, сооружения или иного объекта, а также на выполнение монтажных, пусконаладочных и иных неразрывно связанных со строящимся объектом работ."}]},{"n":"Статья 108","title":"Договор возмездного оказания услуг","sub":[{"n":"1","text":"По договору возмездного оказания услуг исполнитель обязуется по заданию заказчика оказать услуги (совершить определенные действия или осуществить определенную деятельность), а заказчик обязуется оплатить эти услуги."},{"n":"2","text":"Правила настоящей главы применяются к договорам оказания услуг связи, медицинских, ветеринарных, аудиторских, консультационных, информационных услуг, услуг по обучению, туристическому обслуживанию и иных."},{"n":"3","text":"Заказчик вправе отказаться от исполнения договора возмездного оказания услуг при условии оплаты исполнителю фактически понесенных им расходов."}]},{"h":"Глава 18. Перевозка и Транспортная экспедиция"},{"n":"Статья 109","title":"Договор перевозки груза","sub":[{"n":"1","text":"По договору перевозки груза перевозчик обязуется доставить вверенный ему отправителем груз в пункт назначения и выдать его уполномоченному на получение груза лицу (получателю), а отправитель обязуется уплатить за перевозку груза установленную плату."},{"n":"2","text":"Заключение договора перевозки груза подтверждается составлением и выдачей отправителю груза транспортной накладной (коносамента или иного документа на груз, предусмотренного соответствующим транспортным уставом или кодексом)."},{"n":"3","text":"Перевозчик несет ответственность за сохранность груза, происшедшую после принятия его к перевозке и до выдачи грузополучателю, если не докажет, что утрата или повреждение груза произошли вследствие обстоятельств, которые перевозчик не мог предотвратить."}]},{"n":"Статья 110","title":"Договор перевозки пассажира","sub":[{"n":"1","text":"По договору перевозки пассажира перевозчик обязуется перевезти пассажира в пункт назначения, а в случае сдачи пассажиром багажа также доставить багаж в пункт назначения и выдать его управомоченному на получение багажа лицу; пассажир обязуется уплатить установленную плату за проезд, а при сдаче багажа и за провоз багажа."},{"n":"2","text":"Заключение договора перевозки пассажира удостоверяется билетом, а сдача пассажиром багажа багажной квитанцией."},{"n":"3","text":"Перевозчик несет ответственность за вред, причиненный жизни или здоровью пассажира, в соответствии с правилами, установленными законом."}]},{"n":"Статья 111","title":"Договор транспортной экспедиции","sub":[{"n":"1","text":"По договору транспортной экспедиции одна сторона (экспедитор) обязуется за вознаграждение и за счет другой стороны (клиента-грузоотправителя или грузополучателя) выполнить или организовать выполнение определенных договором экспедиции услуг, связанных с перевозкой груза."},{"n":"2","text":"Договор транспортной экспедиции может быть заключен как на организацию перевозки груза в целом, так и на выполнение отдельных операций."},{"n":"3","text":"Экспедитор несет ответственность перед клиентом за сохранность груза с момента его принятия и до момента выдачи, если не докажет, что утрата, недостача или повреждение груза произошли вследствие обстоятельств, которые экспедитор не мог предотвратить."}]},{"h":"Глава 19. Заем, Кредит и Банковский счет"},{"n":"Статья 112","title":"Договор займа","sub":[{"n":"1","text":"По договору займа одна сторона (займодавец) передает или обязуется передать в собственность другой стороне (заемщику) деньги, вещи, определенные родовыми признаками, или ценные бумаги, а заемщик обязуется возвратить займодавцу такую же сумму денег (сумму займа) или равное количество полученных им других вещей того же рода и качества."},{"n":"2","text":"Договор займа считается заключенным с момента передачи денег или других вещей, если иное не предусмотрено законом или соглашением сторон."},{"n":"3","text":"Займодавец имеет право на получение с заемщика процентов на сумму займа в размерах и в порядке, определенных договором, если иное не предусмотрено законом или договором займа."}]},{"n":"Статья 113","title":"Кредитный договор","sub":[{"n":"1","text":"По кредитному договору банк или иная кредитная организация (кредитор) обязуются предоставить денежные средства (кредит) заемщику в размере и на условиях, предусмотренных договором, а заемщик обязуется возвратить полученную денежную сумму и уплатить проценты за пользование ею."},{"n":"2","text":"К отношениям по кредитному договору применяются правила, предусмотренные для договора займа, если иное не установлено специальными нормами о кредите и не вытекает из существа кредитного договора."},{"n":"3","text":"Кредитор вправе отказаться от предоставления заемщику предусмотренного кредитным договором кредита полностью или частично при наличии обстоятельств, очевидно свидетельствующих о том, что предоставленная заемщику сумма не будет возвращена в срок."}]},{"n":"Статья 114","title":"Договор банковского счета","sub":[{"n":"1","text":"По договору банковского счета банк обязуется принимать и зачислять поступающие на счет, открытый клиенту (владельцу счета), денежные средства, выполнять распоряжения клиента о перечислении и выдаче соответствующих сумм со счета и проведении иных операций по счету."},{"n":"2","text":"Банк может использовать имеющиеся на счете денежные средства, гарантируя право клиента беспрепятственно распоряжаться этими средствами."},{"n":"3","text":"Банк обязан зачислять поступившие на счет клиента денежные средства не позже дня, следующего за днем поступления в банк соответствующего платежного документа, если более короткий срок не предусмотрен договором."}]},{"n":"Статья 115","title":"Договор банковского вклада","sub":[{"n":"1","text":"По договору банковского вклада (депозита) одна сторона (банк), принявшая поступившую от другой стороны (вкладчика) или поступившую для нее денежную сумму (вклад), обязуется возвратить сумму вклада и выплатить проценты на нее на условиях и в порядке, предусмотренных договором."},{"n":"2","text":"Договор банковского вклада, в котором вкладчиком является гражданин, признается публичным договором."},{"n":"3","text":"Договор банковского вклада должен быть заключен в письменной форме. Письменная форма договора банковского вклада считается соблюденной, если внесение вклада удостоверено сберегательной книжкой, сберегательным или депозитным сертификатом либо иным выданным банком вкладчику документом."}]},{"h":"Глава 20. Хранение и Страхование"},{"n":"Статья 116","title":"Договор хранения","sub":[{"n":"1","text":"По договору хранения одна сторона (хранитель) обязуется хранить вещь, переданную ей другой стороной (поклажедателем), и возвратить эту вещь в сохранности."},{"n":"2","text":"В договоре хранения, в котором хранителем является коммерческая организация либо некоммерческая организация, осуществляющая хранение в качестве одной из целей своей профессиональной деятельности (профессиональный хранитель), может быть предусмотрена обязанность хранителя принять на хранение вещь от поклажедателя в предусмотренный договором срок."},{"n":"3","text":"Хранитель обязан принять все предусмотренные договором хранения меры для того, чтобы обеспечить сохранность переданной на хранение вещи."}]},{"n":"Статья 117","title":"Договор страхования","sub":[{"n":"1","text":"По договору имущественного страхования одна сторона (страховщик) обязуется за обусловленную договором плату (страховую премию) при наступлении предусмотренного в договоре события (страхового случая) возместить другой стороне (страхователю) или иному лицу, в пользу которого заключен договор, причиненные вследствие этого события убытки в застрахованном имуществе либо убытки в связи с иными имущественными интересами страхователя в пределах определенной договором суммы (страховой суммы)."},{"n":"2","text":"По договору личного страхования страховщик обязуется за обусловленную плату уплатить единовременно или выплачивать периодически обусловленную договором сумму в случае причинения вреда жизни или здоровью самого страхователя или другого гражданина, достижения им определенного возраста или наступления в его жизни иного предусмотренного договором события."},{"n":"3","text":"Страхование осуществляется на основании договоров имущественного или личного страхования, заключаемых гражданином или юридическим лицом со страховой организацией."}]},{"h":"Глава 21. Поручение, Комиссия и Агентирование"},{"n":"Статья 118","title":"Договор поручения","sub":[{"n":"1","text":"По договору поручения одна сторона (поверенный) обязуется совершить от имени и за счет другой стороны (доверителя) определенные юридические действия. Права и обязанности по сделке, совершенной поверенным, возникают непосредственно у доверителя."},{"n":"2","text":"Доверитель обязан уплатить поверенному вознаграждение, если это предусмотрено законом, иными правовыми актами или договором поручения."},{"n":"3","text":"Поверенный обязан исполнять данное ему поручение в соответствии с указаниями доверителя. Указания доверителя должны быть правомерными, осуществимыми и конкретными."}]},{"n":"Статья 119","title":"Договор комиссии","sub":[{"n":"1","text":"По договору комиссии одна сторона (комиссионер) обязуется по поручению другой стороны (комитента) за вознаграждение совершить одну или несколько сделок от своего имени, но за счет комитента."},{"n":"2","text":"По сделке, совершенной комиссионером с третьим лицом, приобретает права и становится обязанным комиссионер, хотя бы комитент и был назван в сделке или вступил с третьим лицом в непосредственные отношения по исполнению сделки."},{"n":"3","text":"Комитент обязан уплатить комиссионеру вознаграждение, а в случае, если комиссионер принял на себя ручательство за исполнение сделки третьим лицом (делькредере), также дополнительное вознаграждение в размере и в порядке, установленных в договоре."}]},{"n":"Статья 120","title":"Агентский договор","sub":[{"n":"1","text":"По агентскому договору одна сторона (агент) обязуется за вознаграждение совершать по поручению другой стороны (принципала) юридические и иные действия от своего имени, но за счет принципала либо от имени и за счет принципала."},{"n":"2","text":"По сделке, совершенной агентом с третьим лицом от своего имени и за счет принципала, приобретает права и становится обязанным агент, хотя бы принципал и был назван в сделке или вступил с третьим лицом в непосредственные отношения."},{"n":"3","text":"По сделке, совершенной агентом с третьим лицом от имени и за счет принципала, права и обязанности возникают непосредственно у принципала."}]},{"n":"Статья 121","title":"Договор доверительного управления имуществом","sub":[{"n":"1","text":"По договору доверительного управления имуществом одна сторона (учредитель управления) передает другой стороне (доверительному управляющему) на определенный срок имущество в доверительное управление, а другая сторона обязуется осуществлять управление этим имуществом в интересах учредителя управления или указанного им лица (выгодоприобретателя)."},{"n":"2","text":"Передача имущества в доверительное управление не влечет перехода права собственности на него к доверительному управляющему."},{"n":"3","text":"Договор доверительного управления имуществом заключается на срок, не превышающий пяти лет, если иное не установлено законом."}]},{"n":"Статья 122","title":"Договор коммерческой концессии (Франчайзинг)","sub":[{"n":"1","text":"По договору коммерческой концессии одна сторона (правообладатель) обязуется предоставить другой стороне (пользователю) за вознаграждение на срок или без указания срока право использовать в предпринимательской деятельности пользователя комплекс принадлежащих правообладателю исключительных прав."},{"n":"2","text":"Договор коммерческой концессии заключается в письменной форме и подлежит государственной регистрации."},{"n":"3","text":"Пользователь обязан использовать при осуществлении предусмотренной договором деятельности фирменное наименование, товарный знак, знак обслуживания или иное средство индивидуализации правообладателя указанным в договоре образом."}]},{"h":"Глава 22. Простое товарищество и Рента"},{"n":"Статья 123","title":"Понятие договора простого товарищества","sub":[{"n":"1","text":"По договору простого товарищества (договору о совместной деятельности) двое или несколько лиц (товарищей) обязуются соединить свои вклады и совместно действовать без образования юридического лица для извлечения прибыли или достижения иной не противоречащей закону цели."},{"n":"2","text":"Сторонами договора простого товарищества, заключаемого для осуществления предпринимательской деятельности, могут быть только индивидуальные предприниматели и (или) коммерческие организации."},{"n":"3","text":"Вкладом товарища признается все то, что он вносит в общее дело, в том числе деньги, иное имущество, профессиональные и иные знания, навыки и умения, а также деловая репутация и деловые связи."},{"n":"4","text":"Товарищи несут ответственность по общим обязательствам всем своим имуществом, если договором не предусмотрено иное."}]},{"n":"Статья 124","title":"Договор ренты и пожизненного содержания с иждивением","sub":[{"n":"1","text":"По договору ренты одна сторона (получатель ренты) передает другой стороне (плательщику ренты) в собственность имущество, а плательщик ренты обязуется в обмен на полученное имущество периодически выплачивать получателю ренту в виде определенной денежной суммы либо предоставления средств на его содержание в иной форме."},{"n":"2","text":"По договору пожизненного содержания с иждивением получатель ренты - гражданин передает принадлежащие ему жилой дом, квартиру, земельный участок или иную недвижимость в собственность плательщика ренты, который обязуется осуществлять пожизненное содержание с иждивением гражданина и (или) указанного им третьего лица."},{"n":"3","text":"Договор ренты подлежит нотариальному удостоверению, а договор, предусматривающий отчуждение недвижимого имущества под выплату ренты, подлежит также государственной регистрации."}]},{"h":"Глава 23. Публичные обещания и конкурсы"},{"n":"Статья 125","title":"Публичное обещание награды","sub":[{"n":"1","text":"Лицо, объявившее публично о выплате денежного вознаграждения или выдаче иной награды (о выплате награды) тому, кто совершит указанное в объявлении правомерное действие в указанный в нем срок, обязано выплатить обещанную награду любому, кто совершил соответствующее действие, в частности отыскал утраченную вещь или сообщил лицу, объявившему о награде, необходимые сведения."},{"n":"2","text":"Объявление о награде должно содержать указание на существо заданий и срок их выполнения."},{"n":"3","text":"Если обещанная награда зависит от результатов конкурса, объявление о награде должно содержать условия конкурса."}]},{"n":"Статья 126","title":"Публичный конкурс","sub":[{"n":"1","text":"Лицо, объявившее публично о выплате денежного вознаграждения или выдаче иной награды (о выплате награды) за лучшее выполнение работы или достижение иных результатов (публичный конкурс), должно выплатить обусловленную награду тому, кто в соответствии с условиями проведения конкурса признан его победителем."},{"n":"2","text":"Публичный конкурс должен быть направлен на достижение каких-либо общественно полезных целей."},{"n":"3","text":"Публичный конкурс может быть открытым, когда предложение организатора конкурса принять в нем участие обращено ко всем желающим путем объявления в печати или иных средствах массовой информации, либо закрытым, когда предложение принять участие в конкурсе направляется определенному кругу лиц по выбору организатора конкурса."}]},{"n":"Статья 127","title":"Проведение игр и пари","sub":[{"n":"1","text":"Требования граждан и юридических лиц, связанные с организацией игр и пари или с участием в них, не подлежат судебной защите, за исключением требований лиц, принявших участие в играх или пари под влиянием обмана, насилия, угрозы или злонамеренного соглашения их представителя с организатором игр или пари."},{"n":"2","text":"Проведение игр и пари осуществляется в порядке, предусмотренном законом и (или) соглашением сторон."}]},{"h":"Глава 24. Внедоговорные обязательства"},{"n":"Статья 128","title":"Общие основания ответственности за причинение вреда (Деликт)","sub":[{"n":"1","text":"Вред, причиненный личности или имуществу гражданина, а также вред, причиненный имуществу юридического лица, подлежит возмещению в полном объеме лицом, причинившим вред."},{"n":"2","text":"Законом обязанность возмещения вреда может быть возложена на лицо, не являющееся причинителем вреда. Законом или договором может быть установлена обязанность причинителя вреда выплатить потерпевшим компенсацию сверх возмещения вреда."},{"n":"3","text":"Лицо, причинившее вред, освобождается от возмещения вреда, если докажет, что вред причинен не по его вине. Законом может быть предусмотрено возмещение вреда и при отсутствии вины причинителя вреда."}]},{"n":"Статья 129","title":"Ответственность за вред, причиненный источником повышенной опасности","sub":[{"n":"1","text":"Юридические лица и граждане, деятельность которых связана с повышенной опасностью для окружающих (использование транспортных средств, механизмов, электрической энергии высокого напряжения, атомной энергии, взрывчатых веществ, сильнодействующих ядов и т.п.), обязаны возместить вред, причиненный источником повышенной опасности."},{"n":"2","text":"Обязанность возмещения вреда возлагается на юридическое лицо или гражданина, которые владеют источником повышенной опасности на праве собственности, праве хозяйственного ведения или праве оперативного управления либо на ином законном основании."},{"n":"3","text":"Владелец источника повышенной опасности освобождается от ответственности, если докажет, что вред возник вследствие непреодолимой силы или умысла потерпевшего."}]},{"n":"Статья 130","title":"Возмещение морального вреда","sub":[{"n":"1","text":"Если гражданину причинен моральный вред (физические или нравственные страдания) действиями, нарушающими его личные неимущественные права либо посягающими на принадлежащие гражданину нематериальные блага, суд может возложить на нарушителя обязанность денежной компенсации указанного вреда."},{"n":"2","text":"Компенсация морального вреда осуществляется в денежной форме."},{"n":"3","text":"Размер компенсации морального вреда определяется судом в зависимости от характера причиненных потерпевшему физических и нравственных страданий, а также степени вины причинителя вреда в случаях, когда вина является основанием возмещения."}]},{"n":"Статья 131","title":"Обязательства вследствие неосновательного обогащения","sub":[{"n":"1","text":"Лицо, которое без установленных законом, иными правовыми актами или сделкой оснований приобрело или сберегло имущество (приобретатель) за счет другого лица (потерпевшего), обязано возвратить последнему неосновательно приобретенное или сбереженное имущество (неосновательное обогащение)."},{"n":"2","text":"Правила, предусмотренные настоящей главой, применяются независимо от того, явилось ли неосновательное обогащение результатом поведения приобретателя имущества, самого потерпевшего, третьих лиц или произошло помимо их воли."},{"n":"3","text":"Имущество, составляющее неосновательное обогащение приобретателя, должно быть возвращено потерпевшему в натуре, за исключением случаев, когда такое возвращение невозможно."}]},{"h":"Часть третья"},{"h":"Раздел V. Наследственное право"},{"h":"Глава 25. Общие положения о наследовании"},{"n":"Статья 132","title":"Наследование","sub":[{"n":"1","text":"При наследовании имущество умершего (наследство, наследственное имущество) переходит к другим лицам в порядке универсального правопреемства, то есть в неизмененном виде как единое целое и в один и тот же момент, если из закона не вытекает иное."},{"n":"2","text":"Наследование регулируется действующими нормативными правовыми актами в сфере гражданских взаимоотношений."},{"n":"3","text":"В состав наследства входят принадлежавшие наследодателю на день открытия наследства вещи, иное имущество, в том числе имущественные права и обязанности."}]},{"n":"Статья 133","title":"Основания наследования","sub":[{"n":"1","text":"Наследование осуществляется по завещанию, по наследственному договору и по закону."},{"n":"2","text":"Наследование по закону имеет место, когда и поскольку оно не изменено завещанием, а также в иных случаях, установленных нормами законодательства."},{"n":"3","text":"Часть имущества, оставшаяся незавещанной, распределяется между наследниками по закону, призываемыми к наследованию в установленном порядке."}]},{"n":"Статья 134","title":"Открытие наследства","sub":[{"n":"1","text":"Наследство открывается со смертью гражданина. Объявление судом гражданина умершим влечет за собой те же правовые последствия, что и смерть гражданина."},{"n":"2","text":"Временем открытия наследства является момент смерти гражданина. При объявлении гражданина умершим днем открытия наследства является день вступления в законную силу решения суда об объявлении его умершим."},{"n":"3","text":"Местом открытия наследства является последнее место жительства наследодателя."}]},{"n":"Статья 135","title":"Недостойные наследники","sub":[{"n":"1","text":"Не наследуют ни по закону, ни по завещанию граждане, которые своими умышленными противоправными действиями, направленными против наследодателя, кого-либо из его наследников или против осуществления последней воли наследодателя, выраженной в завещании, способствовали либо пытались способствовать призванию их самих или других лиц к наследованию либо способствовали или пытались способствовать увеличению причитающейся им или другим лицам доли наследства, если эти обстоятельства подтверждены в судебном порядке."},{"n":"2","text":"Не наследуют по закону родители после детей, в отношении которых родители были в судебном порядке лишены родительских прав и не восстановлены в этих правах ко дню открытия наследства."},{"n":"3","text":"По требованию заинтересованного лица суд отстраняет от наследования по закону граждан, злостно уклонявшихся от выполнения лежавших на них в силу закона обязанностей по содержанию наследодателя."}]},{"h":"Глава 26. Наследование по завещанию и по закону"},{"n":"Статья 136","title":"Наследование по завещанию","sub":[{"n":"1","text":"Гражданин может совершить завещание, содержащее распоряжение о принадлежащем ему имуществе на случай смерти."},{"n":"2","text":"Завещание может быть совершено гражданином, обладающим в момент его совершения дееспособностью в полном объеме."},{"n":"3","text":"Завещание должно быть составлено в письменной форме и удостоверено нотариусом. Несоблюдение правил о письменной форме завещания и его удостоверении влечет за собой недействительность завещания."},{"n":"4","text":"Завещатель вправе совершить завещание, содержащее распоряжение о любом имуществе, в том числе о том, которое он может приобрести в будущем. Завещатель может распорядиться своим имуществом или какой-либо его частью, составив одно или несколько завещаний."}]},{"n":"Статья 137","title":"Очередность наследования по закону","sub":[{"n":"1","text":"Наследники по закону призываются к наследованию в порядке очередности, предусмотренной законодательством."},{"n":"2","text":"Наследниками первой очереди по закону являются дети, супруг и родители наследодателя. Внуки наследодателя и их потомки наследуют по праву представления."},{"n":"3","text":"Наследники каждой последующей очереди призываются к наследованию при отсутствии наследников предшествующих очередей, то есть если нет наследников предшествующих очередей, или никто из них не принял наследства."},{"n":"4","text":"Наследование по праву представления означает, что доля наследника по закону, умершего до открытия наследства или одновременно с наследодателем, переходит по праву представления к его соответствующим потомкам и делится между ними поровну."}]},{"n":"Статья 138","title":"Обязательная доля в наследстве","sub":[{"n":"1","text":"Несовершеннолетние или нетрудоспособные дети наследодателя, его нетрудоспособные супруг и родители, а также нетрудоспособные иждивенцы наследодателя наследуют независимо от содержания завещания не менее половины доли, которая причиталась бы каждому из них при наследовании по закону (обязательная доля)."},{"n":"2","text":"Право на обязательную долю в наследстве удовлетворяется из оставшейся незавещанной части наследственного имущества, даже если это приведет к уменьшению прав других наследников по закону на эту часть имущества."},{"n":"3","text":"Если незавещанной части имущества недостаточно для осуществления права на обязательную долю, это право удовлетворяется из той части имущества, которая завещана."}]},{"n":"Статья 139","title":"Наследственная трансмиссия","sub":[{"n":"1","text":"Если наследник, призванный к наследованию по завещанию или по закону, умер после открытия наследства, не успев его принять в установленный срок, право на принятие причитавшегося ему наследства переходит к его наследникам по закону, а если все наследственное имущество было завещано - к его наследникам по завещанию (наследственная трансмиссия)."},{"n":"2","text":"Право на принятие наследства в порядке наследственной трансмиссии не входит в состав наследства, открывшегося после смерти такого наследника."}]},{"n":"Статья 140","title":"Завещательный отказ (Легат)","sub":[{"n":"1","text":"Завещатель вправе возложить на одного или нескольких наследников по завещанию или по закону исполнение за счет наследства какой-либо обязанности имущественного характера в пользу одного или нескольких лиц (отказополучателей), которые приобретают право требовать исполнения этой обязанности (завещательный отказ)."},{"n":"2","text":"Завещательный отказ должен быть установлен в завещании. Содержание завещания может исчерпываться завещательным отказом."},{"n":"3","text":"Отказополучателями могут быть лица, как входящие, так и не входящие в число наследников по закону."}]},{"n":"Статья 141","title":"Приращение наследственных долей","sub":[{"n":"1","text":"Если наследник не примет наследство, откажется от наследства, не указав при этом, что отказывается в пользу другого наследника, не будет иметь права наследовать или будет отстранен от наследования, его доля в наследстве переходит к наследникам по закону, призванным к наследованию, пропорционально их наследственным долям."},{"n":"2","text":"Если наследодатель завещал все имущество определенным наследникам, часть наследства, причитавшаяся наследнику, отказавшемуся от наследства или отпавшему по иным основаниям, переходит к остальным наследникам по завещанию пропорционально их наследственным долям, если только завещанием не предусмотрено иное распределение этой части наследства."}]},{"h":"Глава 27. Принятие и отказ от наследства"},{"n":"Статья 142","title":"Способы и сроки принятия наследства","sub":[{"n":"1","text":"Для приобретения наследства наследник должен его принять. Для принятия наследства не требуется согласие других наследников."},{"n":"2","text":"Принятие наследства осуществляется подачей по месту открытия наследства нотариусу заявления наследника о принятии наследства либо заявления наследника о выдаче свидетельства о праве на наследство."},{"n":"3","text":"Наследство может быть принято в течение шести месяцев со дня открытия наследства."}]},{"n":"Статья 143","title":"Отказ от наследства","sub":[{"n":"1","text":"Наследник вправе отказаться от наследства в пользу других лиц или без указания лиц, в пользу которых он отказывается от наследственного имущества."},{"n":"2","text":"Отказ от наследства не может быть впоследствии изменен или взят обратно."},{"n":"3","text":"Отказ от наследства совершается подачей по месту открытия наследства нотариусу заявления наследника об отказе от наследства."}]},{"n":"Статья 144","title":"Раздел наследства по соглашению между наследниками","sub":[{"n":"1","text":"Наследственное имущество, которое находится в общей долевой собственности двух или нескольких наследников, может быть разделено по соглашению между ними."},{"n":"2","text":"Соглашение о разделе наследства, в состав которого входит недвижимое имущество, заключается в письменной форме и подлежит государственной регистрации."},{"n":"3","text":"При наличии зачатого, но еще не родившегося наследника раздел наследства может быть осуществлен только после рождения такого наследника."}]},{"n":"Статья 145","title":"Охрана наследства и управление им","sub":[{"n":"1","text":"Нотариус по месту открытия наследства принимает меры по охране наследства и управлению им в интересах наследников, отказополучателей, кредиторов или иных заинтересованных лиц."},{"n":"2","text":"Нотариус принимает меры по охране наследства и управлению им по заявлению одного или нескольких наследников, исполнителя завещания, органа местного самоуправления или иных лиц, действующих в интересах сохранения наследственного имущества."},{"n":"3","text":"Входящее в состав наследства имущество, не требующее управления, передается наследникам, а если оно не может быть передано — на хранение."}]},{"n":"Статья 146","title":"Наследование отдельных видов имущества","sub":[{"n":"1","text":"В состав наследства входят принадлежавшие наследодателю на день открытия наследства вещи, иное имущество, в том числе имущественные права и обязанности."},{"n":"2","text":"Наследование земельных участков, предприятий, авторских прав и иных отдельных видов имущества осуществляется в соответствии с правилами, установленными настоящим Кодексом и другими законами."},{"n":"3","text":"При наследовании предприятия как имущественного комплекса наследники, являющиеся индивидуальными предпринимателями или коммерческими организациями, имеют преимущественное право на получение предприятия в счет своей наследственной доли."}]},{"h":"Раздел VI. Международное частное право"},{"h":"Глава 28. Квалификация и применение иностранного права"},{"n":"Статья 147","title":"Определение права, подлежащего применению к гражданско-правовым отношениям","sub":[{"n":"1","text":"Право, подлежащее применению к гражданско-правовым отношениям с участием иностранных граждан или иностранных юридических лиц либо гражданско-правовым отношениям, осложненным иным иностранным элементом, определяется на основе международных договоров, нормативных актов и обычаев."},{"n":"2","text":"Выбор права подлежащего применению, сделанный сторонами правоотношения, должен быть явно выражен или прямо вытекать из условий договора и совокупности обстоятельств дела."},{"n":"3","text":"Если невозможно определить право, подлежащее применению, применяется право страны, с которой гражданско-правовое отношение наиболее тесно связано."}]},{"n":"Статья 148","title":"Личный закон физического лица","sub":[{"n":"1","text":"Личным законом физического лица считается право страны, гражданство которой это лицо имеет."},{"n":"2","text":"Если лицо наряду с гражданством Российской Федерации имеет гражданство иностранного государства, его личным законом является российское право."},{"n":"3","text":"Личным законом лица без гражданства считается право страны, в которой лицо имеет место жительства."},{"n":"4","text":"Личным законом беженца считается право страны, предоставившей ему убежище."}]},{"n":"Статья 149","title":"Личный закон юридического лица","sub":[{"n":"1","text":"Личным законом юридического лица считается право страны, где учреждено юридическое лицо."},{"n":"2","text":"На основе личного закона юридического лица определяются, в частности, статус организации в качестве юридического лица, организационно-правовая форма, требования к наименованию, вопросы создания, реорганизации и ликвидации, порядок приобретения гражданских прав и принятия на себя гражданских обязанностей."}]},{"n":"Статья 150","title":"Автономия воли сторон","sub":[{"n":"1","text":"Стороны договора могут при совершении сделки или в последующем выбрать по соглашению между собой право, которое подлежит применению к их правам и обязанностям по этому договору."},{"n":"2","text":"Соглашение сторон о выборе подлежащего применению права должно быть явно выражено или прямо вытекать из условий договора либо совокупности обстоятельств дела."},{"n":"3","text":"Выбор сторонами договора подлежащего применению права, сделанный после заключения договора, имеет обратную силу и считается действительным с момента заключения договора без ущерба для прав третьих лиц."}]},{"n":"Статья 151","title":"Оговорка о публичном порядке","sub":[{"n":"1","text":"Иностранное право не применяется в случаях, когда последствия его применения явно противоречили бы основам правопорядка (публичному порядку) Российской Федерации."},{"n":"2","text":"В случае отказа в применении иностранного права применяется соответствующее российское право."},{"n":"3","text":"Отказ в применении иностранного права не может быть основан лишь на отличии политической или экономической системы соответствующего иностранного государства от политической или экономической системы Российской Федерации."}]},{"n":"Статья 152","title":"Взаимность и реторсии","sub":[{"n":"1","text":"Применение иностранного права осуществляется независимо от того, применяется ли в соответствующем иностранном государстве к отношениям такого рода российское право, за исключением случаев, когда применение иностранного права на началах взаимности предусмотрено законом."},{"n":"2","text":"В случае, когда в иностранном государстве установлены ограничения, затрагивающие интересы российских граждан и юридических лиц, Правительством Российской Федерации могут быть установлены ответные ограничения (реторсии) в отношении прав граждан и юридических лиц соответствующего иностранного государства."}]},{"h":"Часть четвертая"},{"h":"Раздел VII. Права на результаты интеллектуальной деятельности и средства индивидуализации"},{"h":"Глава 29. Общие положения об интеллектуальных правах"},{"n":"Статья 153","title":"Интеллектуальные права","sub":[{"n":"1","text":"На результаты интеллектуальной деятельности и приравненные к ним средства индивидуализации (результаты интеллектуальной деятельности и средства индивидуализации) признаются интеллектуальные права, которые включают исключительное право, являющееся имущественным правом."},{"n":"2","text":"В случаях, предусмотренных законом, на результаты интеллектуальной деятельности и средства индивидуализации признаются также личные неимущественные права и иные права (право следования, право доступа и другие)."},{"n":"3","text":"Интеллектуальные права не зависят от права собственности на материальный носитель (вещь), в котором выражены соответствующий результат интеллектуальной деятельности или средство индивидуализации."}]},{"n":"Статья 154","title":"Исключительное право","sub":[{"n":"1","text":"Гражданин или юридическое лицо, обладающие исключительным правом на результат интеллектуальной деятельности или на средство индивидуализации (правообладатель), вправе использовать такой результат или такое средство по своему усмотрению любым не противоречащим закону способом."},{"n":"2","text":"Правообладатель может распоряжаться исключительным правом на результат интеллектуальной деятельности или на средство индивидуализации, если законом не предусмотрено иное."},{"n":"3","text":"Другие лица не могут использовать соответствующие результат интеллектуальной деятельности или средство индивидуализации без согласия правообладателя, за исключением случаев, предусмотренных настоящим законодательством."}]},{"n":"Статья 155","title":"Договоры о передаче интеллектуальных прав","sub":[{"n":"1","text":"По договору об отчуждении исключительного права одна сторона (правообладатель) передает или обязуется передать принадлежащее ей исключительное право на результат интеллектуальной деятельности или на средство индивидуализации в полном объеме другой стороне (приобретателю)."},{"n":"2","text":"По лицензионному договору одна сторона - обладатель исключительного права на результат интеллектуальной деятельности или на средство индивидуализации (лицензиар) предоставляет или обязуется предоставить другой стороне (лицензиату) право использования такого результата или такого средства в предусмотренных договором пределах."},{"n":"3","text":"Лицензионный договор заключается в письменной форме, если законом не предусмотрено иное. Несоблюдение письменной формы влечет недействительность лицензионного договора."},{"n":"4","text":"Лицензионный договор может предусматривать предоставление лицензиату права использования результата интеллектуальной деятельности или средства индивидуализации с сохранением за лицензиаром права выдачи лицензий другим лицам (простая (неисключительная) лицензия) либо без сохранения такого права (исключительная лицензия)."}]},{"n":"Статья 156","title":"Служебные произведения","sub":[{"n":"1","text":"Авторские права на произведение науки, литературы или искусства, созданное в пределах установленных для работника (автора) трудовых обязанностей (служебное произведение), принадлежат автору."},{"n":"2","text":"Исключительное право на служебное произведение принадлежит работодателю, если трудовым или гражданско-правовым договором между работодателем и автором не предусмотрено иное."},{"n":"3","text":"Если работодатель в течение трех лет со дня, когда служебное произведение было предоставлено в его распоряжение, не начнет использование этого произведения, не передаст исключительное право на него другому лицу или не сообщит автору о сохранении произведения в тайне, исключительное право на служебное произведение возвращается автору."}]},{"n":"Статья 157","title":"Открытая лицензия","sub":[{"n":"1","text":"Правообладатель может сделать публично, путем размещения сведений в информационно-телекоммуникационной сети «Интернет», заявление о предоставлении любым лицам возможности безвозмездно использовать принадлежащие ему произведение науки, литературы или искусства либо объект смежных прав на определенных правообладателем условиях и в течение указанного им срока (открытая лицензия)."},{"n":"2","text":"Открытая лицензия является безвозмездной, если ею не предусмотрено иное."}]},{"n":"Статья 158","title":"Принудительная лицензия","sub":[{"n":"1","text":"В случаях, предусмотренных законом, суд может по требованию заинтересованного лица принять решение о предоставлении этому лицу на указанных в решении суда условиях права использования результата интеллектуальной деятельности, исключительное право на который принадлежит другому лицу (принудительная лицензия)."},{"n":"2","text":"Принудительная лицензия может быть предоставлена, в частности, при неиспользовании или недостаточном использовании правообладателем изобретения или промышленного образца, что приводит к недостаточному предложению соответствующих товаров, работ или услуг на рынке."}]},{"n":"Статья 159","title":"Право следования и право доступа","sub":[{"n":"1","text":"В случае отчуждения автором оригинала произведения изобразительного искусства при каждой публичной перепродаже соответствующего оригинала, в которой в качестве продавца, покупателя или посредника участвует юридическое лицо или индивидуальный предприниматель, автор имеет право на получение от продавца вознаграждения в виде процентных отчислений от цены перепродажи (право следования)."},{"n":"2","text":"Автор произведения изобразительного искусства вправе требовать от собственника оригинала произведения предоставления возможности осуществлять право на воспроизведение своего произведения (право доступа)."},{"n":"3","text":"Право следования и право доступа неотчуждаемы и непередаваемы иным способом."}]},{"h":"Глава 30. Авторское право"},{"n":"Статья 160","title":"Объекты авторских прав","sub":[{"n":"1","text":"Объектами авторских прав являются произведения науки, литературы и искусства независимо от достоинств и назначения произведения, а также от способа его выражения."},{"n":"2","text":"К объектам авторских прав относятся в том числе литературные произведения, драматические и музыкально-драматические произведения, хореографические произведения и мимы, аудиовизуальные произведения, произведения живописи, скульптуры, графики, дизайн, программы для ЭВМ."},{"n":"3","text":"Авторские права не распространяются на идеи, концепции, принципы, методы, процессы, системы, способы, решения технических, организационных или иных задач, открытия, факты, языки программирования."}]},{"n":"Статья 161","title":"Автор произведения","sub":[{"n":"1","text":"Автором произведения науки, литературы или искусства признается гражданин, творческим трудом которого оно создано. Лицо, указанное в качестве автора на оригинале или экземпляре произведения, считается его автором, если не доказано иное."},{"n":"2","text":"Граждане, создавшие произведение совместным творческим трудом, признаются соавторами независимо от того, образует ли такое произведение неразрывное целое или состоит из частей, каждая из которых имеет самостоятельное значение."},{"n":"3","text":"Авторство и имя автора охраняются бессрочно. После смерти автора защиту его авторства и имени может осуществлять любое заинтересованное лицо."}]},{"n":"Статья 162","title":"Срок действия исключительного права на произведение","sub":[{"n":"1","text":"Исключительное право на произведение действует в течение всей жизни автора и семидесяти лет, считая с 1 января года, следующего за годом смерти автора."},{"n":"2","text":"Исключительное право на произведение, созданное в соавторстве, действует в течение всей жизни автора, пережившего других соавторов, и семидесяти лет, считая с 1 января года, следующего за годом его смерти."},{"n":"3","text":"По истечении срока действия исключительного права произведение науки, литературы или искусства переходит в общественное достояние."}]},{"h":"Глава 31. Смежные права"},{"n":"Статья 163","title":"Права, смежные с авторскими","sub":[{"n":"1","text":"К смежным правам относятся права на результаты исполнительской деятельности (исполнения), на фонограммы, на сообщение передач организаций эфирного или кабельного вещания, на базы данных, а также на произведения науки, литературы и искусства, обнародованные после их перехода в общественное достояние."},{"n":"2","text":"Смежные права осуществляются с соблюдением авторских прав на произведения науки, литературы и искусства, использованные при создании объекта смежных прав."},{"n":"3","text":"Для возникновения, осуществления и защиты смежных прав не требуется регистрация объекта или соблюдение каких-либо иных формальностей."}]},{"h":"Глава 32. Патентное право"},{"n":"Статья 164","title":"Объекты патентных прав","sub":[{"n":"1","text":"Объектами патентных прав являются результаты интеллектуальной деятельности в научно-технической сфере, отвечающие установленным требованиям к изобретениям и полезным моделям, и результаты художественно-конструкторского проектирования, отвечающие требования к промышленным образцам."},{"n":"2","text":"Изобретению предоставляется правовая охрана, если оно является новым, имеет изобретательский уровень и промышленно применимо."},{"n":"3","text":"Не могут быть объектами патентных прав способы клонирования человека, способы модификации генетической целостности клеток зародышевой линии человека, использование человеческих эмбрионов в промышленных и коммерческих целях."}]},{"n":"Статья 165","title":"Патент","sub":[{"n":"1","text":"Патент на изобретение, полезную модель или промышленный образец удостоверяет приоритет, авторство и исключительное право на соответствующий объект патентных прав."},{"n":"2","text":"Патент выдается федеральным органом исполнительной власти по интеллектуальной собственности по результатам рассмотрения заявки."},{"n":"3","text":"Срок действия исключительного права на изобретение и патента, удостоверяющего это право, составляет двадцать лет с даты подачи заявки."}]},{"h":"Глава 33. Права на средства индивидуализации"},{"n":"Статья 166","title":"Товарный знак и знак обслуживания","sub":[{"n":"1","text":"На товарный знак, то есть на обозначение, служащее для индивидуализации товаров юридических лиц или индивидуальных предпринимателей, признается исключительное право, удостоверяемое свидетельством на товарный знак."},{"n":"2","text":"Правила о товарных знаках соответственно применяются к знакам обслуживания, то есть к обозначениям, служащим для индивидуализации выполняемых работ или оказываемых услуг."},{"n":"3","text":"На территории Российской Федерации действует исключительное право на товарный знак, зарегистрированный федеральным органом исполнительной власти по интеллектуальной собственности."}]},{"n":"Статья 167","title":"Фирменное наименование","sub":[{"n":"1","text":"Юридическое лицо, являющееся коммерческой организацией, выступает в гражданском обороте под своим фирменным наименованием, которое определяется в его учредительных документах и включается в единый государственный реестр юридических лиц при государственной регистрации."},{"n":"2","text":"Фирменное наименование юридического лица должно содержать указание на его организационно-правовую форму и собственное наименование юридического лица, которое не может состоять только из слов, обозначающих род деятельности."},{"n":"3","text":"Распоряжение исключительным правом на фирменное наименование (в том числе путем его отчуждения или предоставления другому лицу права использования) не допускается."}]},{"n":"Статья 168","title":"Наименование места происхождения товара и географическое указание","sub":[{"n":"1","text":"Географическим указанием, которому предоставляется правовая охрана, является обозначение, идентифицирующее происходящий с территории географического объекта товар, определенное качество, репутация или другие характеристики которого в значительной степени связываются с его географическим происхождением."},{"n":"2","text":"Наименованием места происхождения товара является обозначение, представляющее собой современное или историческое, официальное или неофициальное, полное или сокращенное наименование страны, городского или сельского поселения или иного географического объекта."},{"n":"3","text":"Исключительное право на географическое указание и наименование места происхождения товара действует в течение десяти лет со дня подачи заявки в уполномоченный орган."}]},{"h":"Глава 34. Право на секреты производства (Ноу-хау)"},{"n":"Статья 169","title":"Секрет производства (Ноу-хау)","sub":[{"n":"1","text":"Секретом производства (ноу-хау) признаются сведения любого характера (производственные, технические, экономические, организационные и другие) о результатах интеллектуальной деятельности в научно-технической сфере и о способах осуществления профессиональной деятельности, имеющие коммерческую ценность."},{"n":"2","text":"Сведения признаются секретом производства, если они имеют действительную или потенциальную коммерческую ценность в силу неизвестности их третьим лицам, к ним нет свободного доступа на законном основании и обладатель ввел режим коммерческой тайны."},{"n":"3","text":"Исключительное право на секрет производства действует до тех пор, пока сохраняется конфиденциальность сведений, составляющих его содержание."}]},{"h":"Глава 35. Защита интеллектуальных прав"},{"n":"Статья 170","title":"Способы защиты","sub":[{"n":"1","text":"Защита исключительных прав на результаты интеллектуальной деятельности и на средства индивидуализации осуществляется, в частности, путем предъявления требования о признании права — к лицу, которое отрицает или иным образом не признает право."},{"n":"2","text":"Защита осуществляется также путем предъявления требования о пресечении действий, нарушающих право или создающих угрозу его нарушения, — к лицу, совершающему такие действия или осуществляющему необходимые приготовления к ним."},{"n":"3","text":"Обладатель исключительного права вправе требовать от нарушителя возмещения убытков или выплаты компенсации вместо возмещения убытков за каждый случай неправомерного использования."}]},{"n":"Статья 171","title":"Коллективное управление авторскими и смежными правами","sub":[{"n":"1","text":"В случаях, когда осуществление авторских и смежных прав в индивидуальном порядке затруднено, могут создаваться организации по коллективному управлению авторскими и смежными правами."},{"n":"2","text":"Организации по коллективному управлению авторскими и смежными правами действуют на основании устава и осуществляют управление правами на коллективной основе в интересах правообладателей."},{"n":"3","text":"Организация по коллективному управлению авторскими и смежными правами вправе предъявлять требования в суде от имени правообладателей."}]},{"h":"Глава 36. Информационные права и цифровые активы"},{"n":"Статья 172","title":"Цифровые права","sub":[{"n":"1","text":"Цифровыми правами признаются названные в таком качестве в законе обязательственные и иные права, содержание и условия осуществления которых определяются в соответствии с правилами информационной системы, отвечающей установленным законом признакам."},{"n":"2","text":"Осуществление, распоряжение, в том числе передача, залог, обременение цифрового права ограничениями или передача цифрового права в пользование возможно только в информационной системе без обращения к третьим лицам."},{"n":"3","text":"Переход цифрового права на основании сделки не требует согласия должника, если иное не предусмотрено законом."}]},{"n":"Статья 173","title":"Цифровой рубль и платежи","sub":[{"n":"1","text":"Расчеты с использованием цифровых рублей осуществляются путем перевода цифровых рублей оператором платформы цифрового рубля в соответствии с законодательством Российской Федерации."},{"n":"2","text":"Цифровые рубли относятся к безналичным денежным средствам."},{"n":"3","text":"Оборотоспособность и специфические особенности проведения платежных операций с использованием цифровых рублей регулируются профильным законодательством и актами Центрального банка Российской Федерации."}]},{"h":"Глава 37. Окончательные положения"},{"n":"Статья 174","title":"Применение ГК РФ","sub":[{"n":"1","text":"Акты гражданского законодательства не имеют обратной силы и применяются к отношениям, возникшим после введения их в действие."},{"n":"2","text":"По отношениям, возникшим до введения в действие акта гражданского законодательства, он применяется к правам и обязанностям, возникшим после введения его в действие."},{"n":"3","text":"Отношения сторон по договору, заключенному до введения в действие акта гражданского законодательства, регулируются в соответствии с правилами, действовавшими при заключении договора."}]},{"n":"Статья 175","title":"Обычаи","sub":[{"n":"1","text":"Обычаем признается сложившееся и широко применяемое в какой-либо области предпринимательской или иной деятельности, не предусмотренное законодательством правило поведения, независимо от того, зафиксировано ли оно в каком-либо документе."},{"n":"2","text":"Обычаи, противоречащие обязательным для участников соответствующего отношения положениям законодательства или договору, не применяются."},{"n":"3","text":"При наличии противоречий между обычаем и общепринятыми принципами права применяется соответствующий правовой принцип."}]},{"n":"Статья 176","title":"Международные договоры","sub":[{"n":"1","text":"Международные договоры Российской Федерации применяются к отношениям, указанным в настоящем тексте, непосредственно, кроме случаев, когда из международного договора следует, что для его применения требуется издание внутригосударственного акта."},{"n":"2","text":"Если международным договором Российской Федерации установлены иные правила, чем те, которые предусмотрены гражданским законодательством, применяются правила международного договора."},{"n":"3","text":"Решения межгосударственных органов, принятые на основании положений международных договоров Российской Федерации в их истолковании, противоречащем Конституции Российской Федерации, не подлежат исполнению в Российской Федерации."},{"n":"","text":"Президент Российской Федерации Б.Ельцин"},{"n":"","text":"Москва, Кремль"},{"n":"","text":"30 ноября 1994 года"},{"n":"","text":"№ 51-ФЗ"}]}]};
